-- Code generated by game-db import. DO NOT EDIT.
-- Source: Sheets Dump/. Regenerate with `make import`.
-- sudden_death_questions: 309 questions for subject economics.

MERGE INTO sudden_death_questions AS t
USING (
    SELECT v.question_code, 'economics' AS subject, v.chapter_no, v.prompt, v.option_a, v.option_b, v.correct_option, v.difficulty, v.hint, v.explanation
    FROM (VALUES
        ('eco11-01-sd-0001', 1, 'What is science defined as?', 'A systematic body of knowledge', 'A mathematical formulation of nature', 'a', 1, 'Think of knowledge organized systematically.', 'A systematic body of knowledge is correct. Science is organized knowledge; a mathematical formulation of nature is too narrow to define all science.'),
        ('eco11-01-sd-0002', 1, 'While Sociology studies the ''social'' aspect of man as a member of society, Psychology is specifically related to which aspect of human behaviour?', 'Physical aspect', 'Mental aspect', 'b', 1, 'Focus on the mind and thought.', 'Mental aspect is correct. Psychology studies mental processes and behaviour; the physical aspect is not its defining focus.'),
        ('eco11-01-sd-0003', 1, 'The term ''Economics'' is derived from which Greek word and meaning?', '''Nomos'', meaning allocation of scarce resources', '''Oikonomia'', meaning management of the household', 'b', 1, 'The word comes from an ancient Greek term.', '''Oikonomia'', meaning management of the household is correct. The term economics derives from the Greek ''Oikonomia''; ''Nomos'' alone is not the word given for its origin.'),
        ('eco11-01-sd-0004', 1, 'Which prominent economist referred to Economics as the ''Queen of Social Sciences''?', 'Paul Samuelson', 'Alfred Marshall', 'a', 1, 'Recall the economist associated with this title.', 'Paul Samuelson is correct. Paul Samuelson referred to Economics as the ''Queen of Social Sciences''; Alfred Marshall is a different economist.'),
        ('eco11-01-sd-0005', 1, 'Essentially, Kautilya''s ''Arthashastra'' is a treatise on which subject in its broadest sense?', 'Household Management', 'Political Economy', 'b', 1, 'Consider the broad relationship between politics and economic affairs.', 'Political Economy is correct. Arthashastra broadly concerns political economy; household management is narrower and does not capture its subject.'),
        ('eco11-01-sd-0006', 1, 'Adam Smith authored his most famous work, ''An Inquiry into the Nature and Causes of the Wealth of Nations'', in which year?', '1776', '1890', 'a', 1, 'Recall the publication year of Smith''s famous work.', '1776 is correct. Adam Smith''s Wealth of Nations was published in 1776; 1890 is associated with Marshall''s Principles of Economics.'),
        ('eco11-01-sd-0007', 1, 'How does classical economist Adam Smith define Economics?', 'A science of scarcity and choice', 'A science of wealth', 'b', 1, 'Focus on Smith''s wealth-oriented definition.', 'A science of wealth is correct. Adam Smith''s definition treats Economics as a science of wealth; material welfare is associated with Marshall''s approach.'),
        ('eco11-01-sd-0008', 1, 'Which of the following principles forms a foundational pillar of Adam Smith''s wealth-oriented economic framework?', 'Laissez-faire (non-intervention of government)', 'Centralized price fixing by public authorities', 'a', 2, 'Think of limited government intervention in markets.', 'Laissez-faire (non-intervention of government) is correct. Laissez-faire emphasizes limited government intervention; centralized price fixing is the opposite approach.'),
        ('eco11-01-sd-0009', 1, 'Adam Smith associated division of labour with which theory?', 'Scarcity theory', 'Growth theory', 'b', 2, 'Consider the theory linked to productivity and output.', 'Growth theory is correct. Adam Smith linked division of labour with growth theory; scarcity theory focuses on limited means and choice.'),
        ('eco11-01-sd-0010', 1, 'Which of the following economists is categorized under the Modern School of Thought (from 20th century till date)?', 'J. M. Keynes', 'David Ricardo', 'a', 1, 'Recall a prominent twentieth-century economist.', 'J. M. Keynes is correct. Keynes belongs to the modern school; David Ricardo is associated with the classical school.'),
        ('eco11-01-sd-0011', 1, 'Who coined the terms ''Micro Economics'' and ''Macro Economics'' in the year 1933?', 'Kenneth Boulding', 'Sir Ragnar Frisch', 'b', 1, 'Think of the economist who introduced the paired terms.', 'Sir Ragnar Frisch is correct. Ragnar Frisch coined the terms Micro Economics and Macro Economics in 1933; Kenneth Boulding later discussed their distinction.'),
        ('eco11-01-sd-0012', 1, 'How does Economics specifically define a ''want'' as compared to everyday language?', 'A feeling of ''lack of satisfaction'' that prompts an individual to satisfy it', 'A legal entitlement guaranteed by the constitution', 'a', 1, 'A want begins with a feeling of insufficiency.', 'A feeling of ''lack of satisfaction'' that prompts an individual to satisfy it is correct. An economic want is a felt lack of satisfaction; a legal entitlement is a right, not a want.'),
        ('eco11-01-sd-0013', 1, 'Which characteristic of human wants is illustrated by the fact that as soon as one want is satisfied, another arises, leading to an unending chain?', 'Wants differ with gender', 'Wants are unlimited', 'b', 1, 'Consider whether human wants eventually come to an end.', 'Wants are unlimited is correct. Wants are unlimited because satisfying one is followed by another; they are not culturally uniform in all cases.'),
        ('eco11-01-sd-0014', 1, 'Eating food every day to satisfy hunger reflects which characteristic of wants?', 'Wants are recurring in nature', 'Wants are static and non-gradable', 'a', 2, 'Think of a want that returns regularly.', 'Wants are recurring in nature is correct. Hunger returns and must be satisfied repeatedly, showing that wants can recur; wants are not static.'),
        ('eco11-01-sd-0015', 1, 'In Figure 1.5, a small child wants toys, a young man wants a motorbike, and an elderly woman wants reading glasses/books. This illustrates that:', 'Wants remain constant throughout life', 'Wants differ with age', 'b', 1, 'Consider how preferences change across life stages.', 'Wants differ with age is correct. The examples reflect changing wants across life stages; wants do not remain constant throughout life.'),
        ('eco11-01-sd-0016', 1, 'Using an umbrella during the monsoon and wearing warm woollen clothes in winter (as shown in Fig. 1.6) demonstrates that:', 'Wants differ with seasons', 'Wants are unaffected by weather', 'a', 1, 'Think about changes in weather across the year.', 'Wants differ with seasons is correct. Umbrellas and woollen clothes meet season-specific wants; weather can influence what people need.'),
        ('eco11-01-sd-0017', 1, 'In economics, how is ''Utility'' defined?', 'The total market price of a manufactured asset', 'The capacity of a commodity to satisfy human wants', 'b', 1, 'Focus on what a good can do for a person.', 'The capacity of a commodity to satisfy human wants is correct. Utility is a good''s capacity to satisfy wants; price is its monetary value.'),
        ('eco11-01-sd-0018', 1, 'When the worth of a commodity or service is expressed in terms of money, it is specifically called its:', 'Price', 'Utility', 'a', 1, 'Think of monetary expression of a commodity''s worth.', 'Price is correct. Price expresses a commodity''s worth in money; utility refers to its capacity to satisfy wants.'),
        ('eco11-01-sd-0019', 1, 'Under the characteristics of wealth, what does ''Scarcity'' specifically require?', 'A commodity must be completely unavailable on the surface of the earth', 'A commodity must be scarce in supply in relation to its demand', 'b', 2, 'Scarcity depends on supply relative to demand.', 'A commodity must be scarce in supply in relation to its demand is correct. Scarcity means supply is limited relative to demand; it does not mean the item must be completely unavailable.'),
        ('eco11-01-sd-0020', 1, 'While a vehicle can be physically moved from one place to another (physical transferability), a parcel of land demonstrates:', 'Notional transferability (transfer of ownership rights)', 'No transferability whatsoever', 'a', 2, 'Consider how ownership of land can change hands.', 'Notional transferability (transfer of ownership rights) is correct. Land can be transferred through ownership rights even though the physical land itself cannot be moved.'),
        ('eco11-01-sd-0021', 1, 'What does ''Personal Income'' comprise?', 'Income earned exclusively from contractual monthly wages', 'Earnings received by a person from all sources', 'b', 1, 'Think about the full range of a person''s receipts.', 'Earnings received by a person from all sources is correct. Personal income includes receipts from all sources, not only contractual wages.'),
        ('eco11-01-sd-0022', 1, 'Which type of income remains stable over a period of time (e.g., rent, wages), as opposed to profit which can be positive, negative, or zero?', 'Fixed income', 'Fluctuating income', 'a', 1, 'Focus on income that stays steady over time.', 'Fixed income is correct. Fixed income remains stable over time; fluctuating income changes rather than staying steady.'),
        ('eco11-01-sd-0023', 1, 'In economic theory, how is ''Production'' fundamentally defined?', 'Creation of physical matter out of nothing', 'Creation of utility', 'b', 1, 'Production creates something useful to people.', 'Creation of utility is correct. In economics, production is the creation of utility; it does not mean creating physical matter from nothing.'),
        ('eco11-01-sd-0024', 1, 'Any physical or mental effort undergone during the process of production to earn the reward of ''wages'' is termed:', 'Labour', 'Capital', 'a', 1, 'Think of human effort used in production.', 'Labour is correct. Labour is the physical or mental human effort used in production; capital refers to produced means used for further production.'),
        ('eco11-01-sd-0025', 1, 'What does the economic process of ''Distribution'' refer to?', 'Transporting physical boxes from wholesale markets to retailers', 'Division of factor rewards among different segments of the society', 'b', 2, 'Consider how factor rewards are allocated.', 'Division of factor rewards among different segments of the society is correct. Distribution allocates factor rewards among groups; transporting boxes is physical distribution, not the economic process meant here.'),
        ('eco11-01-sd-0026', 1, 'In economics, ''Exchange'' necessarily refers to:', 'Sale and purchase of goods and services through a monetary transaction', 'Any barter of unwanted personal belongings without valuation', 'a', 2, 'Focus on purchases and sales involving money.', 'Sale and purchase of goods and services through a monetary transaction is correct. Economic exchange involves monetary sales and purchases; barter without a monetary transaction does not fit this definition.'),
        ('eco11-01-sd-0027', 1, 'How does the chapter define ''Consumption''?', 'Mobilising factor rewards into new capital assets', 'Making use of goods and services to satisfy human wants', 'b', 1, 'Think of using goods or services to meet needs.', 'Making use of goods and services to satisfy human wants is correct. Consumption means using goods and services to satisfy wants; mobilizing savings into assets is investment.'),
        ('eco11-01-sd-0028', 1, 'According to the National Income Committee, how must commodities and services be counted in a national estimate?', 'Counted without duplication during a given period', 'At wholesale factor cost including intermediate sales', 'a', 2, 'The key idea is avoiding counting the same output twice.', 'Counted without duplication during a given period is correct. National estimates count output without duplication; counting intermediate sales alongside final output can double-count goods.'),
        ('eco11-01-sd-0029', 1, 'In macroeconomic terms, ''Investment'' refers to:', 'Hoarding cash currency notes in domestic home safes', 'Creation of capital assets through mobilisation of savings', 'b', 1, 'Think of savings used to create productive assets.', 'Creation of capital assets through mobilisation of savings is correct. Investment creates capital assets using savings; simply hoarding cash does not create productive assets.'),
        ('eco11-01-sd-0030', 1, 'Unemployment created as a direct result of fluctuations in the trade cycle is specifically termed:', 'Cyclical unemployment', 'Seasonal unemployment', 'a', 1, 'Focus on unemployment linked to business-cycle changes.', 'Cyclical unemployment is correct. Cyclical unemployment results from trade-cycle fluctuations; seasonal unemployment arises from seasonal changes.'),
        ('eco11-02-sd-0001', 2, 'What is meant by the term ''Barter System''?', 'Exchange of goods directly for other goods', 'Exchange of goods and services for paper currency', 'a', 1, 'A barter exchange involves a direct swap of goods, rather than using money.', 'Barter is the direct exchange of goods for other goods. Exchanging goods for paper currency uses money, so it is not barter.'),
        ('eco11-02-sd-0002', 2, 'Who defined money as ''anything that is generally acceptable as a means of exchange and at the same time acts as a measure and a store of value''?', 'Prof. Walker', 'Prof. Crowther', 'b', 1, 'Recall which economist gave this definition of money.', 'Prof. Crowther defined money as something generally accepted as a medium of exchange and as a measure and store of value. Prof. Walker is associated with the phrase “Money is what money does.”'),
        ('eco11-02-sd-0003', 2, 'Which functional definition of money was given by Prof. Walker?', '''Money is what money does''', '''Money is a link between the present and future''', 'a', 1, 'Think of the brief phrase associated with Prof. Walker.', 'Prof. Walker’s functional definition is “Money is what money does.” The phrase about linking the present and future is associated with Lord J. M. Keynes.'),
        ('eco11-02-sd-0004', 2, 'Which statement accurately describes ''Standard or Full-Bodied Coins''?', 'Coins whose face value is substantially higher than their intrinsic value', 'Coins whose face value is exactly equal to their intrinsic value', 'b', 1, 'Compare a coin’s face value with the value of its metal.', 'A standard or full-bodied coin has a face value equal to its intrinsic value. A coin whose face value exceeds its intrinsic value is a token coin.'),
        ('eco11-02-sd-0005', 2, 'During which historical period were standard coins used in India for some time?', 'British period', 'Mughal period', 'a', 1, 'Recall the period when standard coins were used in India.', 'Standard or full-bodied coins were used in India for some time during the British period, not the Mughal period.'),
        ('eco11-02-sd-0006', 2, 'What defines ''Token Coins'' as explained in the text?', 'Coins whose intrinsic value equals their face value', 'Coins whose face value is higher than their intrinsic value', 'b', 1, 'Focus on face value versus intrinsic value.', 'A token coin has a face value higher than its intrinsic value. A full-bodied coin has equal face and intrinsic values.'),
        ('eco11-02-sd-0007', 2, 'In India today, how are all coins in active circulation categorized?', 'Token coins', 'Standard full-bodied coins', 'a', 1, 'Identify the type of coins commonly circulating in India today.', 'Coins in active circulation in India are categorized as token coins, not standard full-bodied coins.'),
        ('eco11-02-sd-0008', 2, 'Which are examples of plastic money?', 'Cheques and bills of exchange', 'Debit cards and credit cards', 'b', 1, 'Think of the payment cards commonly called plastic money.', 'Debit cards and credit cards are forms of plastic money. Cheques and bills of exchange are credit instruments, not plastic money.'),
        ('eco11-02-sd-0009', 2, 'Which quality of money ensures that transactions of both very small and very large values can be settled smoothly without loss of value?', 'Divisibility', 'Portability', 'a', 1, 'Which quality lets money represent both small and large amounts?', 'Divisibility allows money to be split into smaller denominations for transactions of different values. Portability concerns ease of carrying money.'),
        ('eco11-02-sd-0010', 2, 'The presence of distinct symbols, watermarks, designs, and marks on currency notes to prevent confusion and counterfeiting relates to which quality of money?', 'Portability', 'Cognizability', 'b', 1, 'Look at the features that help people recognize genuine currency.', 'Cognizability means money can be readily recognized through distinct symbols, watermarks, designs, and marks. Stability concerns the steadiness of money’s value.'),
        ('eco11-02-sd-0011', 2, 'Which of the following functions of money is categorized as a ''Primary Function''?', 'Medium of exchange', 'Transfer of value', 'a', 1, 'Recall one of money’s primary functions.', 'A medium of exchange is a primary function of money. Transfer of value is classified as a secondary function.'),
        ('eco11-02-sd-0012', 2, 'What is a price in economics?', 'The ratio of barter goods exchanged between two traders', 'The value of a commodity or service expressed in terms of money', 'b', 1, 'Think about how a commodity’s value is expressed in money.', 'Price is the value of a commodity or service expressed in money. A barter ratio expresses an exchange between goods rather than a money price.'),
        ('eco11-02-sd-0013', 2, 'According to Lord J. M. Keynes, how does money act as a store of value?', '''Money is a link between the present and future''', '''Money is what money does''', 'a', 1, 'Recall Lord Keynes’s description of money as a store of value.', 'Lord J. M. Keynes described money as “a link between the present and future.” “Money is what money does” is associated with Prof. Walker.'),
        ('eco11-02-sd-0014', 2, 'Who formulated the contingent functions of money described in the chapter?', 'Prof. Crowther', 'Prof. Kinley', 'b', 1, 'Recall the economist associated with contingent functions of money.', 'Prof. Kinley formulated the contingent functions of money. Prof. Crowther is associated with a definition of money based on its exchange, measure, and store-of-value roles.'),
        ('eco11-02-sd-0015', 2, 'Commercial banks create credit money primarily on the foundation of which base?', 'Primary cash deposits saved by the public', 'Foreign government currency reserves', 'a', 2, 'Think about the deposits that provide the base for bank credit creation.', 'Commercial banks create credit primarily on the foundation of primary cash deposits saved by the public. Foreign government currency reserves are not the stated base.'),
        ('eco11-02-sd-0016', 2, 'How can black money be earned?', 'It can only be earned through illegal criminal syndicates', 'It can be earned through both legal and illegal means', 'b', 2, 'Consider whether black money can arise only from criminal activity.', 'Black money can be earned through both legal and illegal means when income is not properly accounted for and tax is evaded. It is not limited to criminal syndicates.'),
        ('eco11-02-sd-0017', 2, 'Modern currency coins and notes circulate repeatedly for years without immediate physical destruction. Which specific quality of money does this demonstrate?', 'Durability', 'Stability', 'a', 1, 'Which quality allows money to remain usable over time?', 'Durability means currency can circulate repeatedly without being physically destroyed quickly. Homogeneity means units of the same denomination are alike.'),
        ('eco11-03-sd-0001', 3, 'What is the statistical procedure of dividing a given set of data into equal parts called?', 'Dispersion', 'Partitioning', 'b', 1, 'Think of the term for splitting data into parts.', 'Partitioning divides data into equal parts. Dispersion describes how spread out the data are.'),
        ('eco11-03-sd-0002', 3, 'Values that divide a given data set into a required number of equal parts are known as:', 'Extreme Values', 'Partition Values', 'b', 1, 'These values mark the boundaries between equal data groups.', 'Partition values divide a dataset into a required number of equal parts. Extreme values are unusually high or low observations.'),
        ('eco11-03-sd-0003', 3, 'In statistical terminology, partition values such as quartiles, deciles, and percentiles are collectively referred to as:', 'Fractiles', 'Parameters', 'a', 1, 'Recall the general statistical term for these dividing values.', 'Quartiles, deciles, and percentiles are types of fractiles. Parameters are numerical characteristics of a population or distribution.'),
        ('eco11-03-sd-0004', 3, 'Partition values form an integral part of which branch of statistics?', 'Descriptive statistics', 'Inferential statistics', 'a', 1, 'Think of the branch that summarizes observed data.', 'Partition values are part of descriptive statistics, which summarizes data. Inferential statistics uses sample data to draw conclusions about a population.'),
        ('eco11-03-sd-0005', 3, 'What term describes extreme values situated on the lower or higher sides in magnitude?', 'Quartiles', 'Outliers', 'b', 1, 'Look for the term for unusually extreme observations.', 'Outliers are unusually low or high observations. Quartiles divide ordered data into four parts.'),
        ('eco11-03-sd-0006', 3, 'Prof. P. C. Mahalanobis formulated India''s industrialization strategy for which Five Year Plan?', 'Second Five Year Plan (1956-61)', 'First Five Year Plan (1951-56)', 'a', 1, 'Recall the plan associated with rapid industrialization.', 'P. C. Mahalanobis formulated the industrialization strategy for the Second Five Year Plan. The First Five Year Plan preceded it and focused more on agriculture.'),
        ('eco11-03-sd-0007', 3, 'What is the statistical measure of comparison between two data sets devised by P. C. Mahalanobis called?', 'Mahalanobis distance', 'Mahalanobis index', 'a', 1, 'The measure is named after the statistician who devised it.', 'Mahalanobis distance measures separation between data points or distributions. “Mahalanobis index” is not the name of this measure.'),
        ('eco11-03-sd-0008', 3, 'Which date has been designated by the Government of India as National ''Statistics Day'' in honour of P. C. Mahalanobis?', '29th June', '2nd October', 'a', 1, 'It coincides with P. C. Mahalanobis''s birth anniversary.', 'National Statistics Day is observed on 29th June, the birth anniversary of P. C. Mahalanobis. 2nd October is Gandhi Jayanti.'),
        ('eco11-03-sd-0009', 3, 'Which identity equates the median with a quartile, decile, and percentile?', 'Q2 = D4 = P40 = Median', 'Q2 = D5 = P50 = Median', 'b', 1, 'Look for the identity representing the middle of ordered data.', 'Q2, D5, P50, and the median each represent the 50th-percentile position. D4 and P40 represent the 40th-percentile position, not the median.'),
        ('eco11-03-sd-0010', 3, 'Which partition value is used to study financial information, including economic, stock, and sales data?', 'Standard deviations', 'Quartiles', 'b', 1, 'These values split ordered data into four equal groups.', 'Quartiles are used to analyze financial, stock, sales, and survey data. Standard deviation measures dispersion rather than dividing data into four groups.'),
        ('eco11-03-sd-0011', 3, 'Which partition value is used to measure test scores, health indicators, household wealth, and percentile wages?', 'Percentiles', 'Deciles', 'a', 1, 'Think of the measure commonly used for test-score rankings.', 'Percentiles indicate position within 100 equal parts and are used for test scores and wealth measures. Deciles divide data into ten equal parts.'),
        ('eco11-03-sd-0012', 3, 'Deciles divide observations into ten equal parts. How many decile points are there?', '10 points (D1 to D10)', '9 points (D1 to D9)', 'b', 1, 'Ten equal sections require internal dividing points.', 'Nine decile points divide observations into ten equal parts. Ten internal points would create eleven sections.'),
        ('eco11-03-sd-0013', 3, 'In a frequency distribution, what does the cumulative frequency of the last class equal?', 'The class width (h)', 'The total frequency (n or Sigma f)', 'b', 1, 'Cumulative frequency adds frequencies up through the final class.', 'The final cumulative frequency equals the sum of all frequencies, n or Σf. Class width is the difference between class boundaries.'),
        ('eco11-03-sd-0014', 3, 'Which measure of central tendency is classified as a positional average rather than a mathematical average?', 'Median', 'Arithmetic Mean', 'a', 1, 'This positional average is the middle value of ordered data.', 'The median is a positional average determined by the middle position in ordered data. The arithmetic mean is calculated from the sum of values divided by their count.'),
        ('eco11-04-sd-0001', 4, 'On which date was the State of Maharashtra officially formed?', '1st May 1960', '1st November 1956', 'a', 1, 'This date is celebrated annually across the state as Maharashtra Day.', 'The State of Maharashtra was officially formed on 1st May 1960. 1st November 1956 marks the earlier reorganization under the States Reorganisation Act when the bilingual Bombay State was created.'),
        ('eco11-04-sd-0002', 4, 'How is the State of Maharashtra administratively divided?', '35 districts under 6 revenue divisions', '36 districts under 6 revenue divisions', 'b', 1, 'The administrative divisions include Konkan, Pune, Nashik, Aurangabad, Amravati, and Nagpur.', 'Maharashtra is administratively divided into 36 districts grouped across 6 revenue divisions. 35 districts is incorrect as Palghar was carved out as the 36th district.'),
        ('eco11-04-sd-0003', 4, 'What was the sex ratio in Maharashtra as recorded in the 2011 Census?', '929 females per 1000 males', '940 females per 1000 males', 'a', 1, 'The figure is slightly under 930 females per 1000 males.', 'According to the 2011 Census, Maharashtra''s sex ratio was 929 females per 1000 males, whereas 940 females per 1000 males was the national average for India.'),
        ('eco11-04-sd-0004', 4, 'What was the state literacy rate of Maharashtra according to the 2011 Census?', '74.0%', '82.3%', 'b', 1, 'More than eight out of ten individuals were recorded as literate in the state.', 'Maharashtra recorded a literacy rate of 82.3% in the 2011 Census, whereas 74.0% corresponds to the all-India national average literacy rate.'),
        ('eco11-04-sd-0005', 4, 'What is the direct economic effect of the decrease in the average size of land holdings in agriculture?', 'Rapid expansion of commercial dairy farming', 'Low farm productivity', 'b', 2, 'When farm holdings fragment into tiny uneconomic plots, operational efficiency falls.', 'Continuous subdivision and fragmentation of farm plots leads directly to low farm productivity because small plots cannot sustain modern farming techniques efficiently, unlike dairy farming expansion.'),
        ('eco11-04-sd-0006', 4, 'What landmark national policy reform in the early 1990s cleared the path for Foreign Direct Investment (FDI) in India?', 'The Liberalisation Act of 1991', 'The Foreign Exchange Regulation Act of 1973', 'a', 1, 'The economic reforms launched in 1991 dismantled industrial licensing and opened foreign investment caps.', 'The Liberalisation Act of 1991 introduced landmark economic deregulation that opened India to foreign direct investment, whereas the Foreign Exchange Regulation Act of 1973 historically restricted foreign equity participation.'),
        ('eco11-04-sd-0007', 4, 'Which sector is both the largest employment generating and fastest growing sector in Maharashtra''s economy?', 'Service Sector', 'Industrial Sector', 'a', 1, 'This tertiary sector encompasses banking, IT, communication, and transport.', 'The service sector contributes over half of the state''s income and is the fastest growing and largest employment provider, outpacing the industrial sector.'),
        ('eco11-04-sd-0008', 4, 'How is the overall infrastructure of the state classified?', 'Agricultural Infrastructure and Industrial Infrastructure', 'Economic Infrastructure and Social Infrastructure', 'b', 1, 'The classification divides physical production utilities from human capital development facilities.', 'Infrastructure is fundamentally classified into Economic Infrastructure (energy, transport, communications) and Social Infrastructure (education, healthcare), rather than sectoral divisions.'),
        ('eco11-04-sd-0009', 4, 'Which group of components falls under Economic Infrastructure?', 'Energy, Transport, and Communication', 'Health and Education', 'a', 2, 'These utilities facilitate the physical production and distribution of goods and services.', 'Energy, transport, and communication directly facilitate production and trade and are part of Economic Infrastructure, whereas health and education form Social Infrastructure.'),
        ('eco11-04-sd-0010', 4, 'In which two cities of Maharashtra has the Metro Railway started operations?', 'Mumbai and Nagpur', 'Mumbai and Pune', 'a', 1, 'One city is located on the Konkan coast and the other is in the Vidarbha region.', 'Metro rail transit operationalized first in Mumbai and Nagpur. Pune was still constructing its initial metro corridors during that period.'),
        ('eco11-04-sd-0011', 4, 'Which Central Government initiative is being promoted by Maharashtra for port-led economic development?', 'Bharatmala Programme', 'Sagarmala Programme', 'b', 1, 'The programme''s name relates to coastal shipping and maritime ports.', 'The Sagarmala Programme is dedicated to port-led modernization and coastal logistics, whereas the Bharatmala Programme focuses on national highway and roadway corridors.'),
        ('eco11-04-sd-0012', 4, 'In educational initiatives, what does ''Inclusive Education'' specifically cater to?', 'Industrial apprentices seeking polytechnic diplomas', 'Differently abled children with special needs', 'b', 1, 'It integrates children facing physical or developmental challenges into general schools.', 'Inclusive education focuses on bringing differently abled children with special needs into mainstream schooling environments, rather than technical industrial apprentices.'),
        ('eco11-04-sd-0013', 4, 'Which innovative schemes are implemented with community participation to enhance adult literacy in Maharashtra?', '''Each one Teach one'' and ''Sakshar Bharat Abhiyan''', '''Sarva Shiksha Abhiyan'' and ''Rashtriya Uchchatar Shiksha Abhiyan''', 'a', 1, 'One scheme name encapsulates an individual mentoring another to read and write.', '''Each one Teach one'' and ''Sakshar Bharat Abhiyan'' are designed specifically for adult literacy, while Sarva Shiksha Abhiyan and RUSA cater to elementary and higher university education respectively.'),
        ('eco11-04-sd-0014', 4, 'Which socio-economic development is described as Maharashtra''s greatest contribution to the country?', 'The Co-operative Movement', 'The Green Revolution model', 'a', 1, 'This movement emphasizes grassroots self-help, shared ownership, and equality.', 'The Co-operative Movement pioneered in Maharashtra across credit, dairy, and agro-processing is widely recognized as the state''s greatest socio-economic contribution to India, whereas the Green Revolution originated predominantly in northwestern states.'),
        ('eco11-04-sd-0015', 4, 'What core democratic and social values are fostered by co-operative societies?', 'Centralized state ownership and mandatory collectivization', 'Self-help, democracy, equality, and solidarity', 'b', 1, 'Co-operatives rely on mutual collaboration and equal voice among individual members.', 'Co-operative societies are voluntary organizations rooted in self-help, democratic governance, equality, and solidarity, which opposes compulsory state ownership.'),
        ('eco11-04-sd-0016', 4, 'What is the economic term for investments done by foreign companies in a host country?', 'External Commercial Borrowings (ECB)', 'Foreign Direct Investment (FDI)', 'b', 1, 'This three-letter acronym denotes direct equity investment in business operations.', 'Foreign Direct Investment (FDI) represents capital invested by foreign enterprises into productive domestic assets and businesses, whereas External Commercial Borrowings (ECB) are commercial debt loans.'),
        ('eco11-05-sd-0001', 5, 'According to the 2011 Census, what is the rural population of India and its percentage share in the total population?', '83.25 crores (68.8%)', '68.80 crores (83.25%)', 'a', 1, 'Recall the population count and percentage figures from the 2011 Census.', 'According to the 2011 Census, India''s rural population is 83.25 crores, which represents 68.8% of the total population, not 68.80 crores and 83.25%.'),
        ('eco11-05-sd-0002', 5, 'In economic terms, how is ''rural development'' defined in relation to the broader concept of ''development''?', 'As a completely separate and unrelated discipline', 'As a subset of the broader term development', 'b', 1, 'Consider whether rural progress is part of overall socio-economic progress or entirely detached from it.', 'Rural development is defined as a subset of the broader term development because it connotes overall development of rural areas to improve quality of life, rather than being an unrelated discipline.'),
        ('eco11-05-sd-0003', 5, 'In India, the concept of ''rural development'' originally emerged and remained for a long time associated with which specific field?', 'Agricultural development', 'Heavy urban industrialization', 'a', 1, 'Think about the primary economic livelihood of traditional Indian villages.', 'Rural development originally emerged in the context of farming and was synonymous with agricultural development, whereas heavy industrialization focused on urban manufacturing centers.'),
        ('eco11-05-sd-0004', 5, 'According to the World Bank definition, rural development is a strategy designed to improve the economic and social life of which target group?', 'Large absentee landlords and commercial brokers', 'The rural poor, including small-scale farmers, tenants, and the landless', 'b', 1, 'Focus on the disadvantaged segments of rural society that the World Bank targets for upliftment.', 'The World Bank defines rural development as a strategy specifically designed to uplift the rural poor, such as smallholders, tenants, and the landless, rather than wealthy absentee landlords.'),
        ('eco11-05-sd-0005', 5, 'Which of the following combinations of activities constitutes the ''allied sector'' of agriculture in India?', 'Weaving, pottery, blacksmithing, and carpentry', 'Plantation, forestry, fisheries, dairy, and horticulture', 'b', 1, 'Focus on nature-based and bio-resource activities related to agriculture rather than artisan craftwork.', 'Plantation, forestry, fisheries, dairy, and horticulture constitute the allied agricultural sector, whereas weaving, pottery, blacksmithing, and carpentry represent traditional rural cottage and artisan crafts.'),
        ('eco11-05-sd-0006', 5, 'What is the specific time threshold defining ''Short-Term Credit'' in agricultural finance?', 'Loans not exceeding two years', 'Loans for a period between 2 years and 5 years', 'a', 1, 'Consider the duration needed to finance seasonal working capital needs like seeds and fertilizers.', 'Short-term credit refers to loans not exceeding two years to meet immediate working capital needs, whereas loans for a period between 2 and 5 years are classified as medium-term credit.'),
        ('eco11-05-sd-0007', 5, 'What are the two primary source categories of agricultural credit in India?', 'Non-Institutional sources and Institutional sources', 'Commercial sources and Central budgetary sources', 'a', 1, 'Differentiate between formal regulated organizations and informal private lenders.', 'Agricultural credit in India is categorized into Institutional sources (formal entities like banks and co-operatives) and Non-Institutional sources (informal lenders like moneylenders and traders).'),
        ('eco11-05-sd-0008', 5, 'Which of the following lists represents the ''Other Private Sources'' of non-institutional rural credit in India?', 'State Co-operative Banks and Primary Agricultural Credit Societies', 'Traders, landlords, commission agents, relatives, and friends', 'b', 1, 'Identify non-formal private individuals rather than organized banking institutions.', 'Traders, landlords, commission agents, relatives, and friends are private non-institutional lenders, whereas State Co-operative Banks and Primary Agricultural Credit Societies are formal institutional credit bodies.'),
        ('eco11-05-sd-0009', 5, 'What is the institutional status of the National Bank for Agriculture and Rural Development (NABARD)?', 'The apex banking institution to provide finance for agriculture and rural development', 'A private commercial banking company listed on international bourses', 'a', 1, 'Consider the highest statutory institution governing rural finance in India.', 'NABARD is the apex statutory banking institution for agricultural and rural finance in India, not a privately owned commercial bank.'),
        ('eco11-05-sd-0010', 5, 'NABARD was established on July 12, 1982 with an initial paid-up capital of Rs. 100 crores contributed in what ratio?', '100% by the Reserve Bank of India', '50:50 contribution of Government of India and Reserve Bank of India', 'b', 2, 'Recall the partnership between the central government and the central bank at NABARD''s foundation.', 'At its establishment in 1982, NABARD''s initial capital was contributed equally (50:50) by the Government of India and the Reserve Bank of India, rather than 100% by the RBI.'),
        ('eco11-05-sd-0011', 5, 'What is the three-tier institutional structure of short-term credit co-operatives in India, ordered from grassroots to apex?', 'Primary Agricultural Credit Societies -> District Central Co-operative Banks -> State Co-Operative Banks', 'State Co-Operative Banks -> District Central Co-operative Banks -> Primary Agricultural Credit Societies', 'a', 2, 'Identify the tier that begins at the village level and ascends toward the state level.', 'From grassroots to apex, short-term co-operatives operate with PACS at the village level, DCCBs at the district level, and State Co-operative Banks at the apex, rather than in reverse order.'),
        ('eco11-06-sd-0001', 6, 'India’s population is measured through a census survey once every:', 'Five years', 'Ten years', 'b', 1, 'Think of the standard decennial period used for nationwide counts.', 'A population census in India is conducted once every ten years (decennially), not every five years.'),
        ('eco11-06-sd-0002', 6, 'According to the 2011 census, India’s population was:', '121.02 crores', '102.7 crores', 'a', 1, 'Recall the official total recorded in the 2011 Census.', 'The 2011 Census recorded India''s population at 121.02 crores, whereas 102.7 crores was the population recorded in 2001.'),
        ('eco11-06-sd-0003', 6, 'India ranks second in the world in population, next to:', 'China', 'Indonesia', 'a', 1, 'Identify the East Asian neighbor historically holding the top population rank.', 'China historically held the largest population in the world, with India ranking second, while Indonesia ranks fourth globally.'),
        ('eco11-06-sd-0004', 6, 'India accounts for what percentage of the world’s total population?', '17.5%', '2.4%', 'a', 1, 'Differentiate between India''s share of world population and its share of land area.', 'India accounts for approximately 17.5% of the global population, whereas 2.4% represents India''s share of the world''s land area.'),
        ('eco11-06-sd-0005', 6, 'India occupies what percentage of the world’s total land area?', '2.4%', '17.5%', 'a', 1, 'Differentiate between geographical land surface and demographic share.', 'India occupies 2.4% of the world''s geographical area, while supporting 17.5% of the world''s total population.'),
        ('eco11-06-sd-0006', 6, 'In India, population statistics are officially compiled and published by the:', 'National Disaster Management Authority', 'Office of the Registrar General and Census Commissioner of India', 'b', 1, 'Identify the central government authority in charge of conducting the decennial census.', 'The Office of the Registrar General and Census Commissioner of India conducts the census and publishes demographic data, whereas the NDMA manages disaster preparedness and relief.'),
        ('eco11-06-sd-0007', 6, 'Kautilya’s Arthashastra prescribed the collection of population statistics as a measure of state policy for:', 'Industrialisation', 'Taxation', 'b', 1, 'Think of the primary state revenue mechanism in ancient governance.', 'Arthashastra prescribed gathering population data to assess taxable capacity and state revenue, not modern industrial policies.'),
        ('eco11-06-sd-0008', 6, 'Kautilya wrote the Arthashastra in the:', 'Third century B.C.', 'Third century A.D.', 'a', 1, 'Recall the ancient Mauryan era timeframe before the Common Era.', 'The Arthashastra was authored in the third century B.C. during the Mauryan period, not in the third century A.D.'),
        ('eco11-06-sd-0009', 6, 'Which year is popularly labelled as the first modern population census of India?', '1872', '1865', 'a', 1, 'Identify the landmark year in the early 1870s when the first non-synchronous census was taken.', 'The year 1872 is recognized as the first population census in India, marking the culmination of initial census attempts started in 1865.'),
        ('eco11-06-sd-0010', 6, 'World Population Day is observed on 11th July because on that date in 1987:', 'World population crossed 500 crores', 'India crossed 100 crore population', 'a', 2, 'Recall the global population milestone known as ''Five Billion Day''.', 'World Population Day commemorates July 11, 1987, when the world population crossed 5 billion (500 crores), not India''s demographic threshold.'),
        ('eco11-06-sd-0011', 6, 'Which source provides comprehensive information about the size, structure, and characteristics of India’s population?', 'National Population Policy', 'Census Survey', 'b', 1, 'Consider the official statistical data gathering operation rather than a policy statement.', 'The Census Survey gathers and provides primary demographic statistics, whereas the National Population Policy provides policy frameworks and targets.'),
        ('eco11-06-sd-0012', 6, 'The negative population growth rate in India during 1911–1921 was primarily attributed to:', 'Urbanisation', 'Epidemics', 'b', 1, 'Consider widespread diseases like plague, cholera, and the 1918 influenza.', 'Severe epidemics like the Spanish flu, plague, and cholera caused high mortality leading to negative growth, whereas urbanisation tends to accompany growth.'),
        ('eco11-06-sd-0013', 6, 'The period 1971–2001 in India is termed ‘population explosion’ because the annual growth rate was:', 'Less than 1%', 'More than 2%', 'b', 2, 'Identify the high annual percentage growth threshold defining rapid expansion.', 'An annual growth rate exceeding 2% signifies explosive growth, while a rate under 1% represents slow demographic growth.'),
        ('eco11-06-sd-0014', 6, 'According to Malthusian theory, population tends to increase in:', 'Geometric progression', 'Arithmetic progression', 'a', 1, 'Recall whether population multiplies (2, 4, 8) or adds (1, 2, 3).', 'Malthus stated that human population increases geometrically (1, 2, 4, 8...), whereas arithmetic progression applies to food production.'),
        ('eco11-06-sd-0015', 6, 'According to Malthusian theory, food supply tends to increase in:', 'Geometric progression', 'Arithmetic progression', 'b', 1, 'Recall whether food production grows linearly or exponentially.', 'Malthus asserted that food supply increases arithmetically (1, 2, 3, 4...), lagging behind geometric population growth.'),
        ('eco11-06-sd-0016', 6, 'Which of the following is a preventive check in Malthusian population theory?', 'Late marriage', 'Natural calamities', 'a', 1, 'Focus on deliberate human decisions rather than external destructive events.', 'Late marriage is a voluntary human check (preventive check), whereas natural calamities are positive checks that increase deaths.'),
        ('eco11-06-sd-0017', 6, 'Which of the following is an example of a positive check in Malthusian population theory?', 'Natural calamities', 'Moral restraint', 'a', 1, 'Identify the nature-imposed check that directly increases the death rate.', 'Natural calamities represent positive checks imposed by nature that raise mortality, whereas moral restraint is a voluntary preventive check.'),
        ('eco11-06-sd-0018', 6, 'Thomas Robert Malthus propounded his population theory in 1798 in the publication titled:', 'Population growth and Economic Development in low-income countries', 'An Essay on the Principle of Population', 'b', 1, 'Identify Malthus''s classic treatise published in 1798.', 'Malthus published his classic essay ''An Essay on the Principle of Population'' in 1798, whereas Coale and Hoover authored the other work.'),
        ('eco11-06-sd-0019', 6, 'The birth rate measures the number of live births occurring per thousand living population during:', 'A decade', 'A year', 'b', 1, 'Identify the standard single-year reporting period for annual birth rates.', 'Crude birth rate is calculated annually as births per thousand people in a single year, not across an entire ten-year decade.'),
        ('eco11-06-sd-0020', 6, 'The birth rate is also commonly termed the:', 'Mortality rate', 'Fertility rate', 'b', 1, 'Recall the term associated with giving birth rather than death.', 'Fertility rate relates to the incidence of births, whereas mortality rate refers to deaths.'),
        ('eco11-06-sd-0021', 6, 'The death rate is also referred to as the:', 'Survival rate', 'Mortality rate', 'b', 1, 'Recall the demographic term specifically denoting deaths.', 'Mortality rate refers specifically to the frequency of deaths, whereas survival rate represents net population addition after deducting deaths from births.'),
        ('eco11-06-sd-0022', 6, 'The rate of natural increase (survival rate) of a population is calculated as:', 'Death rate − Birth rate', 'Birth rate − Death rate', 'b', 1, 'Natural growth equals additions minus deductions.', 'The survival rate is the excess of births over deaths, calculated by subtracting the death rate from the birth rate.'),
        ('eco11-06-sd-0023', 6, 'The theory of demographic transition was propounded by:', 'A. J. Coale and E. M. Hoover', 'Thomas Robert Malthus and Kautilya', 'a', 1, 'Recall the twentieth-century economists known for empirical transition models.', 'Coale and Hoover developed the demographic transition framework for developing nations, while Malthus formulated classical resource-limit theory.'),
        ('eco11-06-sd-0024', 6, 'The demographic transition theory was presented by Coale and Hoover in the book:', 'Population growth and Economic Development in low-income countries', 'An Essay on the Principle of Population', 'a', 1, 'Look for the title focusing on low-income countries and economic development.', 'Coale and Hoover published their theory in ''Population growth and Economic Development in low-income countries'', whereas Malthus wrote ''An Essay on the Principle of Population''.'),
        ('eco11-06-sd-0025', 6, 'According to the demographic transition theory, how many distinct stages does a country pass through?', 'Three', 'Five', 'a', 1, 'Recall the classical three-phase model of demographic transition.', 'The standard demographic transition model classifies transition into three core stages: high stationary, expanding, and low stationary.'),
        ('eco11-06-sd-0026', 6, 'The first stage of demographic transition is characterised by:', 'High birth rate and high death rate', 'Low birth rate and low death rate', 'a', 1, 'Consider the state of an agrarian economy before modern sanitation and medical care.', 'In the initial stage, both birth and death rates remain high, keeping population relatively stable, whereas low rates characterize the advanced third stage.'),
        ('eco11-06-sd-0027', 6, 'Which socioeconomic condition is typical of the first stage of demographic transition?', 'Mass illiteracy and poverty', 'High urbanisation and education', 'a', 2, 'Think of underdeveloped, pre-industrial conditions.', 'The first stage is marked by poverty, agrarian reliance, and illiteracy, whereas high urbanisation and education emerge in later stages.'),
        ('eco11-06-sd-0028', 6, 'Prior to 1921, India was located in which stage of demographic transition?', 'Second stage', 'First stage', 'b', 1, 'Consider the period of high fluctuating mortality prior to the Year of Great Divide.', 'Before 1921, India experienced both high birth rates and high death rates, placing it squarely in the first stage of demographic transition.'),
        ('eco11-06-sd-0029', 6, 'The onset of the second stage of demographic transition is typically driven by:', 'Introduction of industrialisation and beginning of economic development', 'Declining birth rates alongside low death rates', 'a', 2, 'Identify the economic modernization that expands healthcare and food supply.', 'The second stage begins as economic development and industrialisation improve health and lower mortality, while birth rates remain elevated.'),
        ('eco11-06-sd-0030', 6, 'During the second stage of demographic transition, the death rate falls rapidly while the birth rate:', 'Falls rapidly', 'Remains high', 'b', 2, 'Think of the divergence between mortality and fertility that causes population explosion.', 'In the second stage, rapid medical advances slash death rates, but cultural norms keep birth rates high, causing rapid population expansion.'),
        ('eco11-06-sd-0031', 6, 'The third stage of demographic transition is primarily characterized by:', 'Declining birth and death rates with low or stable population', 'High birth rate and rapidly falling death rate', 'a', 2, 'Consider the demographic equilibrium reached in advanced developed economies.', 'The third stage achieves equilibrium through low birth and death rates, whereas a high birth rate with falling death rate defines the second stage.'),
        ('eco11-06-sd-0032', 6, 'Which developmental trend in the third stage of demographic transition promotes smaller family sizes?', 'Rapid industrialisation and urbanisation', 'Dependence on agriculture', 'a', 2, 'Consider the shift from farm labor to city living and modern employment.', 'Industrialisation and urbanisation raise education levels and the cost of rearing children, encouraging smaller families, unlike traditional agriculture.'),
        ('eco11-06-sd-0033', 6, 'Population explosion occurs when the growth of population is:', 'Slower than economic growth', 'Faster than the growth and development of the economy', 'b', 1, 'Think of population outpacing the economic capacity to sustain it.', 'A population explosion takes place when demographic growth outpaces economic development and resource creation.'),
        ('eco11-06-sd-0034', 6, 'The population explosion in India has been primarily caused by:', 'Low birth rate followed by high death rate', 'High birth rate followed by low death rate', 'b', 2, 'Identify the demographic imbalance between births and deaths.', 'Population explosion is driven by a persistent high birth rate coinciding with a steep decline in the death rate.'),
        ('eco11-06-sd-0035', 6, 'Low literacy among females contributes to a high birth rate primarily because it influences:', 'Attitudes toward marriage and childbirth', 'Rapid industrialisation', 'a', 2, 'Consider how social awareness shapes family planning decisions.', 'Lower educational attainment among women reinforces traditional beliefs favoring early marriage and larger families.'),
        ('eco11-06-sd-0036', 6, 'Universalization of marriage contributes to high fertility in India because marriage is viewed as:', 'A religious and social obligation', 'An economic contract', 'a', 2, 'Consider cultural attitudes toward the necessity of marriage.', 'In Indian society, marriage is widely considered a mandatory social and religious duty, ensuring nearly universal marriage and higher aggregate fertility.'),
        ('eco11-06-sd-0037', 6, 'In India, the legal minimum age of marriage has been set at 18 years for females and:', '25 years for males', '21 years for males', 'b', 1, 'Recall the legal statutory age requirement for Indian men.', 'Indian law specifies the minimum legal marriageable age as 21 years for males and 18 years for females.'),
        ('eco11-06-sd-0038', 6, 'Continuing to have children until a desired number of male children is born is termed:', 'Demographic dividend', 'Son meta-preference', 'b', 1, 'Identify the socioeconomic term reflecting gender-biased family size expansion.', 'Son meta-preference refers to parents continuing childbearing until they achieve their desired number of sons, driving up family sizes.'),
        ('eco11-06-sd-0039', 6, 'The joint family system contributes to higher birth rates largely because:', 'There is no individual financial responsibility for child-rearing', 'It delays the age of marriage', 'a', 2, 'Consider how shared child-rearing costs diminish individual economic burdens.', 'In a joint family, the economic cost of raising a child is shared collectively, reducing the perceived financial burden on parents.'),
        ('eco11-06-sd-0040', 6, 'Heavy dependence on agriculture tends to encourage large families because children are seen as:', 'More labour force available for field work', 'An unnecessary household expense', 'a', 2, 'Consider the labor-intensive requirements of rural farming.', 'Agrarian households often perceive additional children as productive farm hands who assist in agricultural operations from an early age.'),
        ('eco11-06-sd-0041', 6, 'Poverty can incentivize larger family sizes because impoverished households often view children as:', 'A reduction in household labour', 'A source of economic support and earnings', 'b', 2, 'Think of extra hands contributing to household income.', 'Impoverished families may view each child as an additional earning hand that supplements total family income and provides old-age support.'),
        ('eco11-06-sd-0042', 6, 'A lack of awareness regarding family welfare services keeps birth rates high because people remain unaware of:', 'Methods of agricultural production', 'Means and techniques of family planning', 'b', 2, 'Focus on access to reproductive health and contraceptive information.', 'Ignorance about contraceptive techniques and family planning services prevents parents from voluntarily limiting family size.'),
        ('eco11-06-sd-0043', 6, 'Underpopulation occurs when:', 'Population growth exceeds the availability of natural resources', 'Natural resources exceed the requirements of the population', 'b', 1, 'Consider the scenario where available resources are underutilized relative to people.', 'Underpopulation exists when a country has abundant natural resources relative to its population size, leaving resources under-exploited.'),
        ('eco11-06-sd-0044', 6, 'Overpopulation is defined as a situation where:', 'Population growth exceeds the availability of natural resources', 'Natural resources exceed the requirements of the population', 'a', 1, 'Think of demographic pressure outstripping resource capacity.', 'Overpopulation occurs when population size exceeds the sustainable supply of available natural resources.'),
        ('eco11-06-sd-0045', 6, 'An optimum population is achieved when:', 'The death rate significantly exceeds the birth rate', 'There is an ideal balance between population size and natural resources', 'b', 1, 'Identify the equilibrium point maximizing per capita welfare.', 'Optimum population represents the point of perfect balance where resources are utilized most efficiently to yield maximum per capita output.'),
        ('eco11-06-sd-0046', 6, 'The major factor in curbing mortality from epidemics like plague and malaria in India was:', 'Dependence on agriculture', 'Improvement in medical and health facilities', 'b', 2, 'Think of modern sanitation, antibiotics, and public health programs.', 'Mass immunization, sanitation improvements, and medical treatments directly lowered disease mortality, whereas agricultural dependence has no direct curative effect.'),
        ('eco11-06-sd-0047', 6, 'A significant decline in the maternal mortality rate is primarily achieved through:', 'Promotion of the joint family system', 'Improvement in medical and institutional health facilities', 'b', 1, 'Focus on institutional deliveries and skilled obstetric care.', 'Access to hospitals, trained midwives, and prenatal medical care directly reduces maternal mortality during childbirth.'),
        ('eco11-06-sd-0048', 6, 'India''s infant mortality rate declined from 146 per 1,000 in 1951 to what figure in 2011?', '64 per 1,000', '47 per 1,000', 'b', 2, 'Recall the official infant mortality rate recorded in the 2011 Census.', 'India''s infant mortality rate dropped significantly to 47 per 1,000 by 2011, having previously been 146 in 1951 and 64 around 2001.'),
        ('eco11-06-sd-0049', 6, 'Higher female literacy lowers infant mortality rates primarily because educated mothers:', 'Encourage earlier marriage for their daughters', 'Provide better nutrition and healthcare for their infants', 'b', 2, 'Consider how health knowledge influences hygiene and infant care.', 'Educated mothers adopt better hygiene, immunization, and feeding practices, directly enhancing infant survival.'),
        ('eco11-06-sd-0050', 6, 'The implementation of the school mid-day meal programme is a government initiative to promote:', 'Use of nutritious food among children', 'Family planning services', 'a', 1, 'Focus on child health, school attendance, and balanced nutrition.', 'The mid-day meal scheme provides balanced daily nutrition to school children, improving health and reducing malnutrition.'),
        ('eco11-06-sd-0051', 6, 'The National Disaster Management Authority (NDMA) in India was constituted in the year:', '2000', '2005', 'b', 1, 'Recall the year the Disaster Management Act was enacted.', 'The NDMA was formally established in 2005 under the Disaster Management Act, not in 2000.'),
        ('eco11-06-sd-0052', 6, 'The primary operational role of the NDMA in preserving human lives is:', 'Expanding the industrial manufacturing sector', 'Mitigating disaster risks and organizing response', 'b', 2, 'Focus on natural and man-made hazard management.', 'NDMA coordinates disaster preparedness, prevention, and relief operations to minimize casualties from hazards.'),
        ('eco11-06-sd-0053', 6, 'Which of the following is a direct environmental consequence of population explosion?', 'Reduced pressure on natural resources', 'Increased pressure on land and agriculture', 'b', 2, 'Think of expanding food requirements encroaching on finite arable land.', 'Rapid population expansion increases the land-man ratio pressure, leading to subdivision and over-exploitation of agricultural land.'),
        ('eco11-06-sd-0054', 6, 'Rapid population growth often accelerates economic inflation because:', 'Aggregate demand for food and essential goods outstrips supply', 'It guarantees an excess surplus of manufactured products', 'a', 1, 'Consider the effect of surging consumer demand on commodity prices.', 'When population expands rapidly, demand for consumer goods surges faster than supply capacity, bidding up general price levels.'),
        ('eco11-06-sd-0055', 6, 'Which of the following is classified as an economic measure to check population explosion?', 'Raising the minimum age of marriage', 'Expansion of the industrial sector', 'b', 2, 'Identify the measure focused on economic structural transformation rather than social legislation.', 'Industrial expansion creates non-agricultural jobs and raises living standards (an economic measure), whereas marriage age laws are social measures.'),
        ('eco11-06-sd-0056', 6, 'Which of the following is classified as a social measure to control population growth?', 'Expansion of industrial manufacturing', 'Improving the status and education of women', 'b', 1, 'Look for an intervention aimed at social equity and empowerment.', 'Elevating women''s education and social status is a social reform, whereas industrial development is categorized as an economic measure.'),
        ('eco11-06-sd-0057', 6, 'Enforcing a higher minimum legal age of marriage is classified as a:', 'Economic measure', 'Social measure', 'b', 1, 'Distinguish between legal/social norms and economic infrastructure.', 'Legislation regulating marriage age addresses social practices and cultural norms, categorizing it as a social measure.'),
        ('eco11-06-sd-0058', 6, 'India became the first country in the world to launch a nationwide Family Planning Programme in:', '1979', '1952', 'b', 1, 'Recall the early post-independence First Five-Year Plan milestone.', 'India pioneered state-sponsored family planning by launching the National Family Planning Programme in 1952.'),
        ('eco11-06-sd-0059', 6, 'The fundamental primary objective of the Family Planning Programme was to:', 'Reduce the birth rate', 'Increase the birth rate', 'a', 1, 'Consider the goal of slowing rapid demographic expansion.', 'The Family Planning Programme was introduced specifically to curtail birth rates and stabilize population growth.'),
        ('eco11-06-sd-0060', 6, 'In demographic policy, the concept of family planning fundamentally refers to:', 'Forced parenthood', 'Planned parenthood', 'b', 1, 'Consider voluntary choices regarding family timing and size.', 'Family planning emphasizes planned and voluntary parenthood, where couples consciously decide their family size.'),
        ('eco11-06-sd-0061', 6, 'India’s Family Planning Programme was formally renamed the Family Welfare Programme in:', '1952', '1979', 'b', 1, 'Recall the late 1970s policy shift expanding focus beyond contraception.', 'In 1979, the government broadened the scope from mere birth control to comprehensive healthcare, renaming it the Family Welfare Programme.'),
        ('eco11-06-sd-0062', 6, 'The Family Welfare Programme integrated family planning services with:', 'Maternal, child health, and nutrition services', 'Industrial and commercial trade services', 'a', 2, 'Think of maternal and child healthcare convergence.', 'The Family Welfare Programme coupled birth control with maternal care, pediatric immunization, and child nutrition.'),
        ('eco11-06-sd-0063', 6, 'India’s National Population Policy (NPP) was formulated and announced in the year:', '2000', '1990', 'a', 1, 'Think of the landmark millennium policy document.', 'The comprehensive National Population Policy (NPP 2000) was officially adopted by the Government of India in February 2000.'),
        ('eco11-06-sd-0064', 6, 'A key target under NPP 2000 was providing free and compulsory school education up to the age of:', '14 years', '18 years', 'a', 1, 'Recall the constitutional age limit for universal elementary schooling.', 'NPP 2000 stipulated free and compulsory elementary schooling up to age 14 to curb child dropout rates.'),
        ('eco11-06-sd-0065', 6, 'NPP 2000 set a target to bring the Infant Mortality Rate (IMR) below:', '30 per 1,000 live births', '64 per 1,000 live births', 'a', 1, 'Recall the specific target below 35 per thousand live births.', 'NPP 2000 aimed to reduce infant mortality to under 30 per 1,000 live births.'),
        ('eco11-06-sd-0066', 6, 'NPP 2000 aimed to reduce the Maternal Mortality Rate (MMR) to below:', '250 per 100,000 live births', '100 per 100,000 live births', 'b', 1, 'Recall the milestone round century number per 100,000 births.', 'The National Population Policy 2000 established the goal of lowering maternal deaths to below 100 per 100,000 live births.'),
        ('eco11-06-sd-0067', 6, 'Under NPP 2000, universal immunization was targeted for all children against:', 'Only tuberculosis', 'All vaccine-preventable diseases', 'b', 1, 'Consider the comprehensive protection offered by childhood vaccine programs.', 'Universal childhood immunization under NPP 2000 targeted complete coverage against all major vaccine-preventable illnesses.'),
        ('eco11-06-sd-0068', 6, 'Regarding female marriage age, NPP 2000 advocated delaying marriage for girls preferably:', 'After 20 years of age', 'Before 18 years of age', 'a', 1, 'Look for the recommended age threshold past teenage years.', 'While legal age is 18, NPP 2000 actively promoted delaying girls'' marriage beyond age 20 to safeguard maternal and reproductive health.'),
        ('eco11-06-sd-0069', 6, 'Which of the following was a primary public health goal included in NPP 2000?', 'Prevention and control of communicable diseases', 'Increase in crude birth rates', 'a', 1, 'Identify the epidemiological disease control target.', 'NPP 2000 prioritized curbing communicable diseases like AIDS and tuberculosis to strengthen national health outcomes.'),
        ('eco11-06-sd-0070', 6, 'NPP 2000 established a long-term goal of achieving a stable population by the year:', '2045', '2025', 'a', 1, 'Recall the target year situated in the mid-twenty-first century.', 'The long-term objective of NPP 2000 is to attain a stable, sustainable population level by 2045.'),
        ('eco11-06-sd-0071', 6, 'In modern development economics, a healthy and educated population is viewed as a nation''s:', 'Permanent economic burden', 'Valuable human resource', 'b', 1, 'Consider people as creators of national productivity rather than pure liabilities.', 'Educated and skilled citizens constitute valuable human capital that powers economic and social advancement.'),
        ('eco11-06-sd-0072', 6, 'Human resources across the globe differ primarily according to their:', 'Educational levels, age structure, and gender composition', 'Uniformity in geographical land distribution', 'a', 1, 'Consider demographic and human capital attributes.', 'Human resources vary across countries in demographic profiles, literacy, skills, and age-sex structures.'),
        ('eco11-06-sd-0073', 6, 'The concept of ''Human Development'' was formally introduced by the UNDP in:', '1990', '2000', 'a', 1, 'Recall the year Mahbub ul Haq and Amartya Sen released the first Human Development Report.', 'The United Nations Development Programme (UNDP) published the inaugural Human Development Report in 1990.'),
        ('eco11-06-sd-0074', 6, 'The Human Development paradigm focuses fundamentally on the enlargement of:', 'Economic, social, cultural, and political choices', 'Only monetary income levels', 'a', 1, 'Think of comprehensive human capabilities beyond just gross income.', 'Human development encompasses expanding people''s overall freedoms and choices across political, social, and economic spheres.'),
        ('eco11-06-sd-0075', 6, 'In human development theory, human development is regarded as the ultimate end, while economic growth is:', 'A means to achieve that end', 'An unrelated obstacle to human wellbeing', 'a', 2, 'Distinguish between the final purpose and the instrument used to attain it.', 'Economic growth provides material resources (the means), but enhancing human capabilities and wellbeing is the ultimate objective (the end).'),
        ('eco11-06-sd-0076', 6, 'Higher levels of human development foster greater political stability by helping to reduce:', 'Civil unrest and social disturbances', 'Agricultural crop yields', 'a', 2, 'Consider how reduced inequality and improved welfare prevent social conflict.', 'Investing in education, health, and equal opportunities alleviates social grievances, curbing civil unrest.'),
        ('eco11-06-sd-0077', 6, 'Human resource development is primarily generated through the provision of:', 'Education and training facilities', 'Military defense equipment', 'a', 1, 'Identify the core investment that develops human skills and knowledge.', 'Building schools, universities, and vocational training centers develops the knowledge and competencies of the labor force.'),
        ('eco11-06-sd-0078', 6, 'Expanding literacy and education among women consistently leads to reductions in:', 'Overall economic productivity', 'Birth rates and infant mortality rates', 'b', 2, 'Consider how maternal education affects reproductive choices and infant care.', 'Female literacy empowers women to make informed reproductive choices and practice better pediatric healthcare, reducing both fertility and infant deaths.'),
        ('eco11-06-sd-0079', 6, 'Human resource development directly enhances the overall quality of life by raising:', 'Inflation rates and cost of living', 'Life expectancy and literacy rates', 'b', 2, 'Identify indicators of human health and educational attainment.', 'Enhanced health and schooling directly increase life expectancy and literacy, fundamental markers of quality of life.'),
        ('eco11-06-sd-0080', 6, 'Human resource development drives scientific research and technological innovation by:', 'Motivating research in higher educational institutions', 'Restricting university academic freedoms', 'a', 2, 'Consider how academic development fosters innovation.', 'Strengthening universities and research institutes nurtures scientific talent, powering technological progress.'),
        ('eco11-06-sd-0081', 6, 'Systematic national investments in nutrition, healthcare, and education yield higher:', 'Human labour productivity', 'National mortality rates', 'a', 2, 'Think of how a healthier, better-educated workforce performs at work.', 'Healthy, well-nourished, and educated individuals work more efficiently, multiplying national economic output.'),
        ('eco11-06-sd-0082', 6, 'The concept of human development is universal because its principles apply to:', 'Only agrarian developing countries', 'Both less developed and highly developed countries', 'b', 1, 'Consider whether human capability expansion applies to all human societies.', 'Every nation, whether rich or developing, faces continuous challenges in expanding human rights, health, and freedoms.'),
        ('eco11-06-sd-0083', 6, 'Population Education as an academic discipline is fundamentally related to:', 'Disaster relief management', 'Human resource development', 'b', 1, 'Consider the educational enhancement of citizens'' understanding and capacity.', 'Population education builds informed awareness, values, and rational decision-making, integral to human resource development.'),
        ('eco11-06-sd-0084', 6, 'Population Education aims to foster responsible attitudes concerning the:', 'Sole expansion of industrial production', 'Quality and quantity of population', 'b', 2, 'Think of balancing population size with human well-being.', 'Population education instills understanding about population dynamics and their direct impact on the quality of human life.'),
        ('eco11-06-sd-0085', 6, 'According to UNESCO, Population Education equips learners to develop attitudes and behaviours toward population that are:', 'Rational and responsible', 'Rigid and dogmatic', 'a', 2, 'Think of scientifically informed and ethical decision-making.', 'UNESCO defines population education as fostering rational, conscious, and responsible family and community decisions.'),
        ('eco11-06-sd-0086', 6, 'A demographic dividend arises when the proportion of working-age people relative to dependents is:', 'High', 'Low', 'a', 1, 'Think of an expanding labor force relative to elderly and child dependents.', 'A demographic dividend occurs when the share of working-age population (15–64) is high, providing an economic growth boost.'),
        ('eco11-07-sd-0001', 7, 'According to NSSO, a person is considered unemployed if they work for less than how many hours per week?', '14 hours', '28 hours', 'a', 1, 'Consider the minimum weekly hour threshold defined by the NSSO for unemployment.', 'Working less than 14 hours a week is classified as unemployed by the NSSO, whereas working 15 to 28 hours indicates underemployment.'),
        ('eco11-07-sd-0002', 7, 'According to NSSO criteria, working 15 to 28 hours a week indicates which employment status?', 'Fully employed', 'Underemployed', 'b', 1, 'This status represents working well below normal working capacity.', 'Working 15 to 28 hours per week reflects underemployment because labour capacity is under-utilised, whereas working 28 hours or more denotes normal employment.'),
        ('eco11-07-sd-0003', 7, 'On a standard basis, a person working eight hours per day for how many days in a year is considered employed?', '273 days', '365 days', 'a', 1, 'Standard person-years assume working eight hours daily for approximately nine months.', 'Standard person-year employment is measured as working 8 hours a day for 273 days in a year, not the entire 365 days.'),
        ('eco11-07-sd-0004', 7, 'What is voluntary unemployment?', 'Being able to work but choosing not to work', 'Being willing to work but unable to find work', 'a', 1, 'Consider whether the person desires to work at the prevailing wage.', 'Voluntary unemployment occurs when an individual is capable of working but chooses not to work, whereas being willing to work but unable to find employment constitutes involuntary unemployment.'),
        ('eco11-07-sd-0005', 7, 'What does underemployment mean?', 'A person has no work due to economic depression', 'A person''s capacity to work is under-utilised', 'b', 1, 'Think about working below one''s potential productive capacity.', 'Underemployment refers to a condition where a worker''s capacity to work is under-utilised or engaged below their potential, rather than being entirely without work during a business downturn.'),
        ('eco11-07-sd-0006', 7, 'What is rural unemployment?', 'Unemployment found in villages', 'Unemployment found in towns and cities', 'a', 1, 'Focus on the geographic settlement type specified.', 'Rural unemployment occurs in villages and countryside areas, whereas joblessness in towns and cities represents urban unemployment.'),
        ('eco11-07-sd-0007', 7, 'What is disguised unemployment also known as?', 'Open unemployment', 'Invisible unemployment', 'b', 1, 'This type of unemployment is hidden because surplus workers appear to be working.', 'Disguised unemployment is termed invisible unemployment because surplus workers appear employed on the surface, unlike open unemployment where joblessness is apparent.'),
        ('eco11-07-sd-0008', 7, 'What does zero marginal productivity indicate in disguised unemployment?', 'Surplus workers add nothing to total output', 'Every additional worker increases total output', 'a', 2, 'Consider the contribution of the last worker added to the production process.', 'Zero marginal productivity means that extra workers do not increase total production, so their withdrawal leaves output unchanged, rather than raising output.'),
        ('eco11-07-sd-0009', 7, 'What is urban unemployment?', 'Unemployment found in villages', 'Unemployment found in towns and cities', 'b', 1, 'Identify the geographical setting associated with urban areas.', 'Urban unemployment refers specifically to joblessness found in towns and cities, whereas unemployment in villages is termed rural unemployment.'),
        ('eco11-07-sd-0010', 7, 'Which factor is a major cause of unemployment among educated youth?', 'Preference for white-collar jobs', 'Shortage of general degree institutions', 'a', 1, 'Think about the job preferences of educated graduates.', 'Educated youth often prefer white-collar desk jobs and hesitate to take up manual or vocational roles, which contributes to joblessness among graduates.'),
        ('eco11-07-sd-0011', 7, 'What is industrial unemployment?', 'Unemployment in the agricultural sector', 'Unemployment in the industrial sector', 'b', 1, 'Look at the economic sector indicated in the name.', 'Industrial unemployment is joblessness among workers in factories and industrial activities, whereas farm joblessness is agricultural unemployment.'),
        ('eco11-07-sd-0012', 7, 'Industrial unemployment is generally described as which form of unemployment?', 'Open unemployment', 'Disguised unemployment', 'a', 1, 'In this form, the unemployed state of workers is clearly visible.', 'Industrial unemployment is typically open unemployment because displaced factory workers are visibly without work, unlike disguised unemployment where idle labour is hidden.'),
        ('eco11-07-sd-0013', 7, 'What causes technological unemployment?', 'Seasonal changes in weather and rainfall', 'Adoption of modern, labour-saving technology', 'b', 1, 'The term itself highlights the primary driver of this unemployment.', 'Technological unemployment arises when modern capital-intensive machinery replaces human labour, whereas seasonal unemployment is driven by weather cycles.'),
        ('eco11-07-sd-0014', 7, 'Why can modern technology displace industrial workers?', 'It is capital-intensive and needs fewer workers', 'It is labour-intensive and needs more workers', 'a', 2, 'Consider whether modern machines replace or require manual labour.', 'Modern technology is capital-intensive, automating processes and needing fewer workers, whereas labour-intensive methods create higher demand for workers.'),
        ('eco11-07-sd-0015', 7, 'What is the typical duration and nature of frictional unemployment?', 'Permanent', 'Temporary', 'b', 1, 'Think about the transition period between leaving one job and finding another.', 'Frictional unemployment is temporary, lasting only while workers switch jobs or during short breakdowns, unlike structural unemployment which can be long-term.'),
        ('eco11-07-sd-0016', 7, 'What causes cyclical unemployment?', 'Fluctuations in the business cycle', 'Permanent changes in industrial structure', 'a', 1, 'Focus on booms and depressions in the macroeconomy.', 'Cyclical unemployment is caused by macroeconomic business cycle swings (booms and recessions), whereas structural unemployment stems from fundamental shifts in the economic structure.'),
        ('eco11-07-sd-0017', 7, 'How does falling production affect employment during an economic depression?', 'It leads to an increase in employment', 'It leads to a decline in employment', 'b', 2, 'When firms produce less, what happens to their demand for labour?', 'When aggregate demand and production fall, firms lay off workers, causing employment to drop rather than rise.'),
        ('eco11-07-sd-0018', 7, 'Structural unemployment is typically described as which kind of phenomenon?', 'Long-term phenomenon', 'Short-term phenomenon', 'a', 1, 'Consider how much time is needed for the economy''s structure and skills to adjust.', 'Structural unemployment is a long-term phenomenon because acquiring new skills and restructuring industries takes considerable time, unlike brief frictional unemployment.'),
        ('eco11-07-sd-0019', 7, 'What is the primary cause of structural unemployment?', 'Temporary machine breakdowns in factories', 'Mismatch between worker skills and available jobs', 'b', 2, 'Think about whether existing skills match newly emerging industry requirements.', 'Structural unemployment occurs when workers'' existing skills do not match the requirements of newly emerging jobs, whereas temporary mechanical breakdowns cause frictional unemployment.'),
        ('eco11-07-sd-0020', 7, 'The replacement of horse carts by auto rickshaws exemplifies which type of unemployment?', 'Structural unemployment', 'Seasonal unemployment', 'a', 2, 'Consider how demand shifted permanently to a new mode of transport.', 'The shift from horse carts to motor vehicles is a permanent structural change rendering old transport skills obsolete, not a seasonal variation.'),
        ('eco11-07-sd-0021', 7, 'Which of the following is an economic effect of unemployment?', 'Loss of human dignity', 'Waste of human resources', 'b', 1, 'Differentiate between material/resource loss and psychological or social effects.', 'The under-utilisation or waste of human labour resources is an economic effect, whereas the loss of human dignity is a social and psychological consequence.'),
        ('eco11-07-sd-0022', 7, 'Which of the following is a social effect of unemployment?', 'Loss of human dignity', 'High dependency ratio', 'a', 1, 'Think of the social and psychological toll on individuals and families.', 'Loss of human dignity and social unrest are social effects of joblessness, whereas a high dependency ratio is primarily an economic effect.'),
        ('eco11-07-sd-0023', 7, 'Which production technique is recommended to reduce unemployment in labour-abundant countries?', 'Capital-intensive techniques', 'Labour-intensive techniques', 'b', 1, 'Think about techniques that utilise more workforce rather than expensive machines.', 'Labour-intensive techniques absorb surplus manpower by using more workers per unit of capital, whereas capital-intensive methods substitute machinery for labour.'),
        ('eco11-07-sd-0024', 7, 'When was the Employment Guarantee Scheme first introduced by the Government of Maharashtra?', '28 March 1972', '1 April 1989', 'a', 1, 'This pioneering rural employment initiative started in the early 1970s.', 'The Employment Guarantee Scheme (EGS) was introduced by the Government of Maharashtra on 28 March 1972, whereas 1989 marked the start of Jawahar Rozgar Yojana.'),
        ('eco11-07-sd-0025', 7, 'When was the Swarnjayanti Gram Swarozgar Yojana (SGSY) launched?', 'December 1997', 'April 1999', 'b', 1, 'It was launched in the late 1990s by restructuring rural self-employment schemes.', 'SGSY was launched in April 1999, whereas December 1997 marked the launch of Swarna Jayanti Shahari Rozgar Yojana (SJSRY).'),
        ('eco11-07-sd-0026', 7, 'What is the funding cost-sharing ratio between Centre and State for SJSRY?', '75% Centre and 25% State', '50% Centre and 50% State', 'a', 2, 'The Central Government bears three-fourths of the scheme expenditure.', 'Under SJSRY, the expenditure is shared between the Central Government and State Governments in a 75:25 ratio, not equally.'),
        ('eco11-07-sd-0027', 7, 'In which year was the Pradhan Mantri Rozgar Yojana (PMRY) implemented?', '1999', '1993', 'b', 1, 'It was introduced in the early 1990s to support educated unemployed youth.', 'PMRY was implemented starting in 1993 to create self-employment for educated youth, whereas 1999 was the launch year of SGSY.'),
        ('eco11-07-sd-0028', 7, 'When was the Training of Rural Youth for Self-Employment (TRYSEM) initiated?', '1979', '1989', 'a', 1, 'This rural youth training scheme began in the late 1970s.', 'TRYSEM was initiated in 1979 to train rural youth for self-employment, while 1989 was when Jawahar Rozgar Yojana was announced.'),
        ('eco11-07-sd-0029', 7, 'Into which rural scheme was TRYSEM merged in April 1999?', 'Pradhan Mantri Rozgar Yojana (PMRY)', 'Swarnjayanti Gram Swarozgar Yojana (SGSY)', 'b', 1, 'It merged into the comprehensive rural self-employment scheme.', 'TRYSEM was merged into SGSY in April 1999 alongside other allied rural programmes, whereas PMRY was a separate scheme targeting educated youth.'),
        ('eco11-07-sd-0030', 7, 'When was the Jawahar Rozgar Yojana (JRY) announced?', '1 April 1989', '28 March 1972', 'a', 1, 'It was launched toward the end of the 1980s for rural employment.', 'JRY was announced on 1 April 1989, whereas 28 March 1972 is the date the Employment Guarantee Scheme was introduced in Maharashtra.'),
        ('eco11-07-sd-0031', 7, 'What was Jawahar Rozgar Yojana (JRY) renamed as from April 1999?', 'Swarnjayanti Gram Swarozgar Yojana (SGSY)', 'Jawahar Gram Samrudhi Yojana (JGSY)', 'b', 1, 'The renamed scheme retained the word ''Jawahar'' in its title.', 'From April 1999, JRY was restructured and renamed Jawahar Gram Samrudhi Yojana (JGSY), whereas SGSY was formed by combining IRDP, TRYSEM, and allied self-employment programmes.'),
        ('eco11-07-sd-0032', 7, 'On which date was NREGS renamed to MGNREGS?', '2 October 2009', '15 August 2014', 'a', 1, 'The renaming took place on Gandhi Jayanti in 2009.', 'NREGS was officially renamed the Mahatma Gandhi National Rural Employment Guarantee Scheme (MGNREGS) on 2 October 2009.'),
        ('eco11-07-sd-0033', 7, 'What type of work is guaranteed to adult volunteers under MGNREGS?', 'Skilled industrial work', 'Unskilled manual work', 'b', 1, 'The scheme focuses on physical labour for public works without requiring technical qualifications.', 'MGNREGS guarantees unskilled manual labour for adult members of rural households, not skilled or specialised industrial employment.'),
        ('eco11-07-sd-0034', 7, 'When was the Deen Dayal Upadhyaya Grameen Kaushalya Yojana announced?', '23 September 2014', '16 January 2016', 'a', 1, 'It was launched in late 2014 under the Ministry of Rural Development.', 'Deen Dayal Upadhyaya Grameen Kaushalya Yojana was announced on 23 September 2014, whereas January 2016 marked the launch of Startup India.'),
        ('eco11-07-sd-0035', 7, 'Which demographic group is the primary focus of Deen Dayal Upadhyaya Grameen Kaushalya Yojana?', 'Urban graduates aged 25 to 45 years', 'Rural youth aged 15 to 35 years from poor families', 'b', 2, 'The scheme targets poor youth in villages for placement-linked skill training.', 'The scheme targets rural poor youth aged 15–35 years to provide skill training and regular wage jobs, not older urban graduates.'),
        ('eco11-07-sd-0036', 7, 'In which year was the first National Policy on Skill Development notified?', '2009', '2015', 'a', 1, 'The first national skill policy came out six years before the revised 2015 policy.', 'The first National Policy on Skill Development was notified in 2009, while 2015 was when the National Policy for Skill Development and Entrepreneurship was introduced.'),
        ('eco11-07-sd-0037', 7, 'In which month and year was the Start up India Initiative introduced?', 'September 2014', 'January 2016', 'b', 1, 'It was launched in the beginning of 2016 to foster young entrepreneurship.', 'Startup India was introduced in January 2016, whereas September 2014 was the launch date of DDU-GKY.'),
        ('eco11-07-sd-0038', 7, 'What total outlay was allocated for the Pradhan Mantri Kaushal Vikas Yojana (2016–20)?', '₹12,000 crores', '₹2,000 crores', 'a', 1, 'The outlay ran into twelve thousand crores.', 'PMKVY (2016–20) was allocated an outlay of ₹12,000 crores to skill Indian youth, not ₹2,000 crores.'),
        ('eco11-07-sd-0039', 7, 'Which government programme specifically aimed to provide self-employment to over one million educated unemployed youth?', 'Jawahar Rozgar Yojana (JRY)', 'Pradhan Mantri Rozgar Yojana (PMRY)', 'b', 2, 'Look for the programme specifically designed for educated youth.', 'PMRY specifically targeted over 1 million educated unemployed youth for self-employment ventures, whereas JRY targeted rural wage employment.'),
        ('eco11-07-sd-0040', 7, 'Which scheme offered monetary rewards to trainees upon successfully completing approved skill training?', 'Pradhan Mantri Kaushal Vikas Yojana (PMKVY)', 'Mahatma Gandhi National Rural Employment Guarantee Scheme (MGNREGS)', 'a', 2, 'Identify the national skill voucher/reward certification scheme.', 'PMKVY provides monetary rewards and skill certificates upon completing approved training courses, whereas MGNREGS provides rural manual wage employment.'),
        ('eco11-08-sd-0001', 8, 'In society, poverty is fundamentally perceived as which of the following?', 'Social exclusion', 'Capital formation', 'a', 1, 'Consider how deprivation of basic needs affects a person''s participation in society.', 'Poverty is perceived as social exclusion because deprivation of basic needs denies individuals opportunities to participate fully in society. Capital formation refers to the accumulation of capital goods, not deprivation.'),
        ('eco11-08-sd-0002', 8, 'For which field of economics was Prof. Amartya Sen awarded the Nobel Memorial Prize in 1998?', 'International trade theory', 'Welfare economics and social choice theory', 'b', 1, 'His work focuses heavily on economic well-being and the welfare of society''s poorest members.', 'Amartya Sen received the Nobel Prize for his contributions to welfare economics and social choice theory. International trade theory addresses the exchange of goods and capital across borders.'),
        ('eco11-08-sd-0003', 8, 'Absolute poverty is primarily measured in terms of:', 'Minimum calorie intake', 'Relative standard of living', 'a', 1, 'This measure is based on the biological minimum nutritional requirement needed for survival.', 'Absolute poverty is measured in terms of minimum daily calorie intake necessary to sustain life. Relative standard of living is used to evaluate relative poverty.'),
        ('eco11-08-sd-0004', 8, 'Which type of poverty can be completely eliminated through effective policy measures?', 'Relative poverty', 'Absolute poverty', 'b', 2, 'One form is based on basic physical subsistence, while the other reflects income differences that always persist.', 'Absolute poverty can be eliminated by ensuring everyone meets minimum basic nutritional and survival requirements. Relative poverty reflects income differences across society and is a universal phenomenon.'),
        ('eco11-08-sd-0005', 8, 'Who headed the 2012 Expert Group constituted to review the methodology for measuring poverty in India?', 'Dr. C. Rangarajan', 'Prof. Ragnar Nurkse', 'a', 1, 'He was a former Governor of the Reserve Bank of India.', 'Dr. C. Rangarajan chaired the 2012 Expert Group on poverty estimation. Ragnar Nurkse was an economist noted for formulating the vicious circle of poverty.'),
        ('eco11-08-sd-0006', 8, 'Which economic factor directly erodes purchasing power and exacerbates hunger and malnutrition among the poor?', 'Economic inequality', 'Inflation', 'b', 2, 'This refers to the continuous and persistent rise in general price levels.', 'Inflation reduces the real purchasing power of income, making basic food commodities unaffordable for low-income households. Economic inequality describes income distribution rather than price increases.'),
        ('eco11-08-sd-0007', 8, 'The concept of the ''Vicious Circle of Poverty'' was formulated by which economist?', 'Prof. Ragnar Nurkse', 'Prof. Amartya Sen', 'a', 1, 'He argued that circular mechanisms link low savings, low investment, and low productivity.', 'Prof. Ragnar Nurkse developed the vicious circle of poverty theory showing how low income leads to low savings and investment. Amartya Sen is noted for the capability approach.'),
        ('eco11-08-sd-0008', 8, 'In which month and year were the UN Sustainable Development Goals (SDGs) officially adopted?', 'January 2016', 'September 2015', 'b', 1, 'They were adopted at the UN Sustainable Development Summit in late 2015.', 'The Sustainable Development Goals were adopted by the international community in September 2015. January 2016 marked when the goals officially came into effect.'),
        ('eco11-08-sd-0009', 8, 'How many Sustainable Development Goals (SDGs) and associated targets were established by the United Nations?', '17 goals and 169 targets', '15 goals and 150 targets', 'a', 1, 'The number of global goals is between 15 and 20.', 'The 2030 Agenda encompasses 17 Sustainable Development Goals and 169 targets. The 15 goals figure is incorrect.'),
        ('eco11-08-sd-0010', 8, 'Which United Nations Sustainable Development Goal targets the eradication of poverty in all its forms?', 'SDG 2', 'SDG 1', 'b', 1, 'This is the very first goal in the UN SDG framework.', 'SDG 1 is specifically designated as ''No Poverty''. SDG 2 targets ''Zero Hunger''.'),
        ('eco11-08-sd-0011', 8, 'Which legislative act was passed in India in 1948 to ensure fair earnings for agricultural and industrial workers?', 'Minimum Wages Act', 'Industrial Disputes Act', 'a', 1, 'This act fixes statutory wage floors across scheduled employments.', 'The Minimum Wages Act was enacted in 1948 to establish statutory wage rates for workers. The Industrial Disputes Act provides machinery for resolving industrial disputes.'),
        ('eco11-08-sd-0012', 8, 'In which years were commercial banks nationalized in India to promote financial inclusion?', '1950 and 1975', '1969 and 1980', 'b', 2, 'The first major phase took place under Prime Minister Indira Gandhi in the late 1960s.', 'Major commercial banks in India were nationalized in two key phases: 14 banks in 1969 and 6 banks in 1980. 1950 and 1975 are incorrect.'),
        ('eco11-08-sd-0013', 8, 'Which fiscal measure is used by governments to reduce income inequality through the tax structure?', 'Progressive Tax Measures', 'Proportional Tax Measures', 'a', 1, 'Under this system, the tax rate increases as the taxable amount increases.', 'Progressive tax measures impose higher tax rates on higher-income earners, helping reduce income disparities. Proportional taxes apply an identical rate across all income brackets.'),
        ('eco11-08-sd-0014', 8, 'Which three colours are utilized in Maharashtra''s Tri Colour Family Ration Card scheme?', 'White, Green, Yellow', 'White, Saffron, Yellow', 'b', 1, 'The colours indicate different household income categories; green is not among them.', 'Maharashtra''s Tri Colour Ration Card system uses White, Saffron, and Yellow cards based on family income criteria. Green is not one of the designated colours.'),
        ('eco11-08-sd-0015', 8, 'On which date is the International Day for the Eradication of Poverty observed globally each year?', '17th October', '10th December', 'a', 1, 'This global day of observance falls in mid-October.', 'The United Nations designated 17th October as the International Day for the Eradication of Poverty. 10th December is Human Rights Day.'),
        ('eco11-09-sd-0001', 9, 'By the end of June 1991, India''s foreign currency reserves were barely enough to finance how many weeks of imports?', '2 weeks', '6 weeks', 'a', 1, 'Think about the critical low point that triggered the 1991 balance of payments crisis.', 'During the June 1991 balance of payments crisis, India''s foreign exchange reserves had dropped to barely two weeks of import cover, far below the safer level of six weeks.'),
        ('eco11-09-sd-0002', 9, 'What was India''s annual rate of inflation in August 1991?', '6.7%', '16.7%', 'b', 1, 'Recall the double-digit peak inflation rate reached during the crisis of 1991.', 'In August 1991, India faced double-digit inflation of 16.7%, reflecting high macroeconomic instability rather than a normal rate of 6.7%.'),
        ('eco11-09-sd-0003', 9, 'The initial process of economic reforms in India began in which year, before gaining full momentum in 1991?', '1980', '1985', 'b', 1, 'Consider the mid-1980s period when early domestic deregulation steps were introduced.', 'Early economic policy adjustments began in 1985, though the comprehensive reform program gained full momentum in 1991; 1980 predates these early initiatives.'),
        ('eco11-09-sd-0004', 9, 'One of the primary objectives of the Economic Policy of 1991 was to integrate the Indian economy into:', 'Globalisation', 'Socialism', 'a', 1, 'Identify the core tenet of opening domestic markets to the worldwide economy.', 'The 1991 reforms aimed to connect India to international markets through globalisation, shifting away from earlier inward-looking socialist models.'),
        ('eco11-09-sd-0005', 9, 'Correcting the disequilibrium in which of the following was an immediate objective of the 1991 reforms?', 'Balance of payments', 'Population growth', 'a', 1, 'Think about India''s external trade and foreign exchange shortfall in 1991.', 'The immediate macro crisis was a severe deficit in the balance of payments, whereas long-term demographic challenges like population growth were not the target of the emergency policy.'),
        ('eco11-09-sd-0006', 9, 'The New Economic Policy of 1991 aimed to significantly expand the participation of which sector?', 'Public sector only', 'Private sector', 'b', 1, 'Identify the sector encouraged through deregulation and delicensing.', 'The 1991 policy sought to boost private sector enterprise by dismantling the license raj, ending the exclusive dominance of the public sector.'),
        ('eco11-09-sd-0007', 9, 'According to the Department for Promotion of Industry and Internal Trade, how many industries presently require compulsory licensing?', '4', '18', 'a', 1, 'Think of the small, tightly restricted group of hazardous and defence-related industries today.', 'Presently, only four sensitive industries require compulsory industrial licensing, down significantly from the 18 retained at the start of delicensing.'),
        ('eco11-09-sd-0008', 9, 'Under the MRTP Act, large industrial houses required mandatory Central government approval for:', 'Import of raw material only', 'Establishment, expansion and merger', 'b', 1, 'Recall the major corporate structural changes regulated to prevent monopoly power.', 'The MRTP Act regulated structural growth—such as establishing new undertakings, expansions, and mergers—rather than everyday operational tasks like importing raw materials.'),
        ('eco11-09-sd-0009', 9, 'Under the MRTP Act of 1969, industrial undertakings were classified as ''MRTP firms'' if their assets reached at least:', 'Rs. 10 crores', 'Rs. 100 crores', 'b', 2, 'Recall the asset threshold that defined large monopoly houses.', 'Companies with assets of Rs. 100 crores or more were classified as MRTP firms and subjected to special regulatory approvals; Rs. 10 crores was an earlier threshold before revision.'),
        ('eco11-09-sd-0010', 9, 'What was the economic impact of abolishing the restrictive provisions of the MRTP Act?', 'It encouraged industrial growth', 'It slowed down industrial growth', 'a', 2, 'Removing regulatory hurdles typically stimulates business investment.', 'Abolishing MRTP curbs removed cumbersome investment clearances and fostered industrial expansion, reversing past stagnation.'),
        ('eco11-09-sd-0011', 9, 'To encourage the small-scale sector, the investment ceiling for small units was raised from Rs. 1 crore to:', 'Rs. 2 crores', 'Rs. 5 crores', 'b', 1, 'Identify the expanded financial ceiling allowed for plant and machinery in small industries.', 'The government raised the investment limit for small-scale industrial units to Rs. 5 crores to facilitate modern plant upgrades, rather than capping it at Rs. 2 crores.'),
        ('eco11-09-sd-0012', 9, 'Under the Industrial Policy of 1991, Foreign Direct Investment (FDI) was initially permitted up to what ceiling in high-priority industries?', '51%', '74%', 'a', 1, 'This was the initial majority equity threshold granted automatic approval in 1991.', 'The 1991 policy initially permitted automatic FDI approval up to 51% majority foreign equity, before higher thresholds like 74% were introduced in subsequent stages.'),
        ('eco11-09-sd-0013', 9, 'Over successive reform phases, the FDI ceiling in select designated sectors was eventually expanded up to:', '100%', '74%', 'a', 2, 'Consider the maximum possible foreign equity ownership permitted in fully opened sectors.', 'India progressively opened select industries to full foreign ownership (100% FDI), moving past intermediate ceilings like 74%.'),
        ('eco11-09-sd-0014', 9, 'The New Economic Policy of 1991 immediately reduced the number of industries reserved for the public sector from 17 to:', '12', '8', 'b', 1, 'Recall the initial sharp reduction in public reservations made in July 1991.', 'The 1991 reforms slashed public sector reserved industries from 17 down to 8, initiating the process of dereservation.'),
        ('eco11-09-sd-0015', 9, 'Following progressive dereservation, how many industries remain exclusively reserved for the public sector today?', '5', '2', 'b', 2, 'Only two sensitive strategic sectors remain under exclusive public ownership.', 'Currently, only two strategic sectors—railways and atomic energy—remain reserved exclusively for the public sector, down from 8.'),
        ('eco11-09-sd-0016', 9, 'Which two industries remain exclusively reserved for the public sector?', 'Railways and Atomic energy', 'Banking and Insurance', 'a', 1, 'Identify the two strategically sensitive state-controlled sectors.', 'Railways and atomic energy remain under exclusive public sector reservation; banking and insurance have both been opened to private competition.'),
        ('eco11-09-sd-0017', 9, 'Special Economic Zones (SEZs) were established primarily to:', 'Promote exports', 'Restrict foreign investment', 'a', 1, 'Consider the export-oriented incentives and duty exemptions provided in these zones.', 'Special Economic Zones are designated duty-free enclaves designed to stimulate export manufacturing and foreign trade, not to restrict foreign inflows.'),
        ('eco11-09-sd-0018', 9, 'Agro Export Zones (AEZs) were established specifically to:', 'Increase import of food grains', 'Encourage agricultural exports', 'b', 2, 'Look at the name: focus on foreign shipments of farm products.', 'Agro Export Zones were set up to boost the export of farm produce and processed agricultural items, not to increase foreign food imports.'),
        ('eco11-09-sd-0019', 9, 'The Insurance Regulatory and Development Authority (IRDA) Act was passed in which year?', '1991', '1999', 'b', 1, 'This financial sector legislation was enacted at the end of the 1990s.', 'The IRDA Act was enacted in 1999 to regulate insurance and open the sector to private players; the 1991 date marks the start of general reforms.'),
        ('eco11-09-sd-0020', 9, 'Prior to the 1991 financial sector reforms, which banking institutions were exclusively permitted to operate?', 'Co-operative and public sector banks', 'Private and foreign banks', 'a', 1, 'Recall which state-backed institutions dominated banking before private entry was allowed.', 'Before 1991, commercial banking was dominated exclusively by public sector and co-operative banks; new domestic private and foreign banks entered only after the 1991 reforms.'),
        ('eco11-09-sd-0021', 9, 'The New Economic Policy (NEP) of 1991 is built upon which three core pillars?', 'Liberalisation, Privatisation, Globalisation', 'Nationalisation, Liberalisation, Privatisation', 'a', 1, 'Commonly abbreviated as the LPG model.', 'The reform framework rests on Liberalisation, Privatisation, and Globalisation (LPG); Nationalisation represents the opposite socialist approach of taking over private firms.'),
        ('eco11-09-sd-0022', 9, 'Which classical economist advocated economic liberalisation as the best route to wealth in ''Wealth of Nations''?', 'Karl Marx', 'Adam Smith', 'b', 2, 'The 18th-century Scottish thinker often called the father of modern economics.', 'Adam Smith argued in ''The Wealth of Nations'' (1776) that free markets and liberalisation promote economic growth, whereas Karl Marx advocated state control and socialism.'),
        ('eco11-09-sd-0023', 9, 'Under banking sector liberalisation, commercial banks gained the autonomy to determine interest rates based on:', 'Government directives', 'Market forces of demand and supply', 'b', 1, 'Consider how competitive market pricing replaced administered rates.', 'Interest rate deregulation allowed commercial banks to set rates using competitive supply and demand forces rather than following rigid government directives.'),
        ('eco11-09-sd-0024', 9, 'The Foreign Exchange Regulation Act (FERA) was replaced by which legislation to liberalise foreign exchange management?', 'FEMA', 'SEBI Act', 'a', 1, 'Identify the act focused on foreign exchange management rather than securities regulation.', 'FERA was replaced by the Foreign Exchange Management Act (FEMA) to facilitate external trade and payments; the SEBI Act governs stock and securities markets.'),
        ('eco11-09-sd-0025', 9, 'The Securities and Exchange Board of India (SEBI) was given statutory status on:', '12th April 1992', '15th August 1991', 'a', 1, 'Statutory recognition came in early 1992 following an official ordinance and act.', 'SEBI was granted full statutory powers under the SEBI Act on 12th April 1992 to protect investors and regulate the capital markets.'),
        ('eco11-09-sd-0026', 9, 'The primary objective of establishing the Securities and Exchange Board of India (SEBI) was to:', 'Regulate foreign trade', 'Protect investors and regulate securities', 'b', 1, 'Focus on the regulator''s mandate concerning capital markets and share trading.', 'SEBI''s core mandate is to regulate the securities market and safeguard the interests of investors, while foreign trade is managed by the Ministry of Commerce and the DGFT.'),
        ('eco11-09-sd-0027', 9, '''Privatisation'' broadly refers to the:', 'Transfer of ownership from public to private', 'Transfer of ownership from private to public', 'a', 1, 'Consider which direction enterprise ownership shifts under market reforms.', 'Privatisation involves transferring ownership or operational control of public enterprises to the private sector; shifting from private to public is nationalisation.'),
        ('eco11-09-sd-0028', 9, 'In Indian economic terminology, BIFR stands for:', 'Bureau of Industrial and Financial Reforms', 'Board of Industrial and Financial Reconstruction', 'b', 1, 'Recall the quasi-judicial board established to revive sick industrial companies.', 'BIFR stands for Board of Industrial and Financial Reconstruction, established to facilitate the rehabilitation or winding up of sick industrial undertakings.'),
        ('eco11-09-sd-0029', 9, 'The concept of ''Miniratna'' for competitive public sector enterprises was introduced by the government in:', '2002', '1997', 'a', 1, 'This status followed the earlier 1997 Navratna scheme to decentralise powers.', 'The Miniratna scheme was instituted in 2002 to confer enhanced managerial and financial autonomy to profit-making CPSEs, whereas Navratna status began in 1997.'),
        ('eco11-09-sd-0030', 9, 'The ''Maharatna'' status for mega Central Public Sector Enterprises was introduced in which year?', '2002', '2009', 'b', 1, 'This is the highest category of financial autonomy, created near the end of the 2000s.', 'The Maharatna category was created in 2009 to empower large CPSEs to expand globally; Miniratna was introduced in 2002.'),
        ('eco11-10-sd-0001', 10, 'Which institution was known as the Central Planning Authority in India before it was replaced in 2015?', 'NITI Aayog', 'Planning Commission', 'b', 1, 'Recall the body that formulated five-year plans before 2015.', 'The Planning Commission served as India''s Central Planning Authority until it was replaced by NITI Aayog in 2015.'),
        ('eco11-10-sd-0002', 10, 'Which characteristic must economic planning objectives possess?', 'They must be permanent and rigid', 'They are realistic and flexible', 'b', 1, 'Recall the adaptable nature of planning targets.', 'Economic planning objectives are designed to be realistic and flexible to adapt to changing circumstances.'),
        ('eco11-10-sd-0003', 10, 'What is described as a concrete step towards the attainment of planning objectives?', 'A survey', 'A target', 'b', 1, 'Think of a specific quantified milestone.', 'A target is a concrete, quantifiable step set towards achieving broader planning objectives.'),
        ('eco11-10-sd-0004', 10, 'What plan duration was generally followed for economic planning in India?', 'Three years', 'Five years', 'b', 1, 'Recall the standard timeframe of India''s formal planning cycles.', 'India traditionally formulated economic development plans spanning a five-year period.'),
        ('eco11-10-sd-0005', 10, 'Which feature explains why economic planning continues beyond one individual plan?', 'It is a continuous process', 'It is based only on annual budgets', 'a', 2, 'Consider whether development goals ever completely end.', 'Economic planning is a continuous, ongoing process aimed at long-term economic development rather than a one-time exercise.'),
        ('eco11-10-sd-0006', 10, 'What does coordination in Indian economic planning primarily ensure?', 'Coordination only among private firms', 'Coordination between the Centre and States', 'b', 1, 'Consider the federal structure of India.', 'In India''s federal structure, economic planning requires close coordination between the Central and State governments.'),
        ('eco11-10-sd-0007', 10, 'How does flexibility help during the implementation of an economic plan?', 'It permits necessary changes according to requirements', 'It fixes targets permanently', 'a', 2, 'Think about how planners respond to unexpected economic shocks.', 'Flexibility allows authorities to adjust priorities and targets as circumstances evolve during implementation.'),
        ('eco11-10-sd-0008', 10, 'In which year did the Government of India establish the Planning Commission?', '1947', '1950', 'b', 1, 'It was established in the year India adopted its Constitution.', 'The Planning Commission was established in March 1950 by a resolution of the Government of India.'),
        ('eco11-10-sd-0009', 10, 'Who was designated as the Ex-Officio Chairman of the Planning Commission?', 'The Finance Minister', 'The Prime Minister', 'b', 1, 'The head of the Union government.', 'The Prime Minister of India served as the Ex-Officio Chairman of the Planning Commission.'),
        ('eco11-10-sd-0010', 10, 'What was the central responsibility of the Planning Commission?', 'Formulation of economic plans', 'Conducting population censuses', 'a', 1, 'Consider its primary institutional mandate.', 'The primary role of the Planning Commission was the formulation of national economic plans.'),
        ('eco11-10-sd-0011', 10, 'What was the primary objective of India''s Second Five Year Plan?', 'Development of agriculture', 'Development of heavy industries', 'b', 1, 'Recall the Mahalanobis strategy focused on basic and capital goods.', 'The Second Five Year Plan (1956–1961) emphasized rapid industrialization and heavy industries, whereas agriculture was the focus of the First Plan.'),
        ('eco11-10-sd-0012', 10, 'What was the main objective of the Fourth Five Year Plan?', 'Removal of Poverty', 'Growth with Stability', 'b', 1, 'It emphasized steady economic expansion alongside self-reliance.', 'The Fourth Five Year Plan (1969–1974) aimed at ''Growth with Stability'', while poverty removal was the focus of the Fifth Plan.'),
        ('eco11-10-sd-0013', 10, 'Which Five Year Plan adopted ''Removal of Poverty'' (Garibi Hatao) as its main objective?', 'Fifth Five Year Plan', 'Fourth Five Year Plan', 'a', 1, 'This plan ran during the mid-to-late 1970s.', 'The Fifth Five Year Plan (1974–1979) focused on poverty removal and self-reliance.'),
        ('eco11-10-sd-0014', 10, 'What was the central objective of the Sixth Five Year Plan?', 'Development of heavy industries', 'Improvement in Quality of Life', 'b', 1, 'This plan (1980–1985) focused on direct attack on poverty and standard of living.', 'The Sixth Five Year Plan prioritized improving the overall quality of life and strengthening infrastructure.'),
        ('eco11-10-sd-0015', 10, 'Which Five Year Plan combined social welfare with poverty eradication as its main objective?', 'Sixth Five Year Plan', 'Seventh Five Year Plan', 'b', 1, 'This plan spanned from 1985 to 1990.', 'The Seventh Five Year Plan (1985–1990) focused on social welfare, food, work, and productivity alongside poverty eradication.'),
        ('eco11-10-sd-0016', 10, 'What was the primary objective of the Eighth Five Year Plan?', 'To give dynamism to the economy', 'Development of agriculture only', 'a', 1, 'It was launched right after the 1991 economic reforms.', 'Launched post-1991 liberalization, the Eighth Plan (1992–1997) focused on modernizing and injecting dynamism into the economy.'),
        ('eco11-10-sd-0017', 10, 'Which Five Year Plan had ''Social Justice and Equality'' as its core objective?', 'Ninth Five Year Plan', 'Eighth Five Year Plan', 'a', 1, 'This plan was launched on the 50th year of Indian Independence (1997).', 'The Ninth Five Year Plan (1997–2002) focused on growth with social justice and equality.'),
        ('eco11-10-sd-0018', 10, 'What was the central theme and objective of the Eleventh Five Year Plan?', 'Faster and more inclusive growth', 'Development of heavy industries', 'a', 1, 'It introduced inclusivity into the national growth vision.', 'The Eleventh Five Year Plan (2007–2012) targeted ''faster and more inclusive growth''.'),
        ('eco11-10-sd-0019', 10, 'What was the overarching objective of the Twelfth Five Year Plan?', 'Growth with Stability', 'Faster, sustainable and more inclusive growth', 'b', 1, 'It added sustainability to the Eleventh Plan''s vision.', 'The Twelfth Five Year Plan (2012–2017) emphasized sustainable growth along with speed and inclusivity.'),
        ('eco11-10-sd-0020', 10, 'What specific gap did the Twelfth Five Year Plan aim to eliminate in school education?', 'Gender and social gaps in enrolment', 'Rural and urban school terms', 'a', 1, 'Think of equity across gender and social communities.', 'The Twelfth Plan aimed to eliminate gender and social disparities across all levels of school enrolment.'),
        ('eco11-10-sd-0021', 10, 'What road-connectivity target was established under the Twelfth Five Year Plan?', 'Connect only district headquarters', 'Connect all villages with all-weather roads', 'b', 1, 'Think of rural all-season road infrastructure.', 'The Twelfth Plan targeted connecting every village across the country with all-weather roads.'),
        ('eco11-10-sd-0022', 10, 'On which date did the Twelfth Five Year Plan formally conclude?', '31 March 2017', '31 March 2015', 'a', 1, 'Recall the final year of India''s five-year planning era.', 'The Twelfth Five Year Plan covered 2012–2017 and formally completed its cycle on 31 March 2017.'),
        ('eco11-10-sd-0023', 10, 'Which governance principles did the establishment of NITI Aayog aim to reinforce?', 'Centralisation and direct administrative control', 'Co-operative federalism and decentralisation', 'b', 1, 'Think about empowering States as equal national partners.', 'NITI Aayog was set up to promote co-operative federalism and decentralized, bottom-up planning.'),
        ('eco11-10-sd-0024', 10, 'On which date was the Cabinet Resolution establishing NITI Aayog sanctioned?', '1 January 2015', '1 January 2014', 'a', 1, 'New Year''s Day of 2015.', 'NITI Aayog was formally established via a Union Cabinet resolution on 1 January 2015.'),
        ('eco11-10-sd-0025', 10, 'Which priority initiative of NITI Aayog directly targets enhancing agricultural earnings?', 'Outcome Budget', 'Doubling of Farmers'' Income', 'b', 1, 'The name of the initiative explicitly highlights farmers'' earnings.', '''Doubling of Farmers'' Income'' is an explicit strategic focus area of NITI Aayog for agricultural development.'),
        ('eco11-10-sd-0026', 10, 'Who nominates the Special Invitees to NITI Aayog?', 'The Prime Minister', 'The President of India', 'a', 1, 'The Chairperson of NITI Aayog.', 'Special Invitees with domain expertise are nominated directly by the Prime Minister.'),
        ('eco11-10-sd-0027', 10, 'Who appoints the Vice Chairperson of NITI Aayog?', 'The Prime Minister', 'The President of India', 'a', 1, 'The Chairperson of NITI Aayog holds this appointing power.', 'The Vice Chairperson of NITI Aayog is appointed directly by the Prime Minister.'),
        ('eco11-10-sd-0028', 10, 'Which approach to governance is promoted by NITI Aayog''s monitoring and evaluation mechanism?', 'Data-driven policy making', 'Policy making without performance metrics', 'a', 1, 'Relying on hard evidence and analytics.', 'Monitoring and evaluation facilitate evidence-based and data-driven policy making across government departments.'),
        ('eco11-10-sd-0029', 10, 'What is the primary platform role played by NITI Aayog in India''s federal structure?', 'Operationalising co-operative federalism', 'Centralising local village planning', 'a', 1, 'Fostering active partnership between the Union and the States.', 'NITI Aayog acts as the primary institutional platform for operationalising co-operative federalism.'),
        ('eco11-10-sd-0030', 10, 'Which institution previously exercised the power to allocate central funds to Ministries and States?', 'Planning Commission', 'NITI Aayog', 'a', 1, 'This financial allocation power was not retained by its successor.', 'The erstwhile Planning Commission had fund-allocating authority, whereas NITI Aayog is purely an advisory think-tank.'),
        ('eco11-10-sd-0031', 10, 'Who appoints the Chief Executive Officer (CEO) of NITI Aayog?', 'The Prime Minister', 'The Union Finance Minister', 'a', 1, 'Appointed by the head of the Union government.', 'The CEO of NITI Aayog is appointed by the Prime Minister for a fixed tenure.'),
        ('eco11-10-sd-0032', 10, 'On which standard accounting principle is the Balance of Payments recorded?', 'Double-entry book-keeping system', 'Single-entry accounting system', 'a', 1, 'Every transaction involves a matching debit and credit entry.', 'The Balance of Payments is constructed using double-entry book-keeping where credits and debits must balance.'),
        ('eco11-10-sd-0033', 10, 'What is a ''baseline'' in economic evaluation and project planning?', 'A starting reference point used for comparison', 'A permanent ceiling on expenditure', 'a', 1, 'The initial benchmark measured before intervention.', 'A baseline represents the initial reference point against which subsequent progress or performance is evaluated.'),
        ('eco11-10-sd-0034', 10, 'What type of financial facility typically requires collateral security?', 'Secured bank loans other than personal loans', 'Non-repayable government grants', 'a', 1, 'An asset pledged as a guarantee for credit repayment.', 'Collateral security is pledged by borrowers to secure commercial and property loans against default risk.'),
        ('eco11-10-sd-0035', 10, 'Which of the following functions as a recognized credit instrument in commercial banking?', 'Tariff rate', 'Cheque', 'b', 1, 'A paper order instructing a bank to pay a specific amount.', 'A cheque is a negotiable credit instrument drawn on a specified bank, unlike a tariff which is a tax on imports.'),
        ('eco11-10-sd-0036', 10, 'What is a major stated objective of government disinvestment in public enterprises?', 'Eliminating all private sector participation', 'Mobilising public resources and improving management efficiency', 'b', 1, 'Think of selling public enterprise shares to raise capital.', 'Disinvestment aims to release public capital and introduce market discipline into state enterprises.'),
        ('eco11-10-sd-0037', 10, 'What characterises an empirical approach in economic analysis?', 'It relies solely on abstract unverified hypotheses', 'It is evidence-based and relies on observed real-world data', 'b', 1, 'Grounding analysis in verifiable factual observations.', 'An empirical approach relies on observed facts and real-world statistical evidence rather than theoretical speculation.'),
        ('eco11-10-sd-0038', 10, 'Which legislation was replaced by the Foreign Exchange Management Act (FEMA) in 1999?', 'FERA (Foreign Exchange Regulation Act)', 'SEZ Act', 'a', 1, 'A stringent earlier law focusing on regulation rather than management.', 'FEMA (1999) replaced the rigid FERA (1973) to facilitate external trade and liberalize foreign exchange.'),
        ('eco11-10-sd-0039', 10, 'Which international organization is the primary source of global poverty data and sets the international poverty line?', 'International Monetary Fund', 'World Bank', 'b', 1, 'The multilateral development bank based in Washington, D.C.', 'The World Bank defines the international poverty line and monitors global poverty statistics.'),
        ('eco11-10-sd-0040', 10, 'What does State Per Capita Income (SPCI) measure?', 'Aggregate industrial production across a State', 'Average income earned per person residing in a State', 'b', 1, 'Per capita divides aggregate income by total population.', 'State Per Capita Income divides total Net State Domestic Product by total state population to find average individual income.'),
        ('eco11-10-sd-0041', 10, 'What does a ''three-tier'' administrative or local governance structure signify?', 'A system organized into two judicial branches', 'A system organized across three distinct administrative levels', 'b', 1, 'For example: Gram Panchayat, Panchayat Samiti, and Zilla Parishad.', 'A three-tier structure consists of three functional levels, such as the Panchayati Raj framework.'),
        ('eco11-10-sd-0042', 10, 'What does the abbreviation ''FDI'' stand for in economic commerce?', 'Foreign Direct Investment', 'Foreign Domestic Income', 'a', 1, 'Cross-border investment in physical business assets.', 'FDI stands for Foreign Direct Investment, referring to lasting cross-border investments in enterprises.'),
        ('eco11-10-sd-0043', 10, 'What is the standard expansion of the macroeconomic abbreviation ''GDP''?', 'Gross Domestic Product', 'Gross Development Programme', 'a', 1, 'The total market value of all final goods and services produced within a country.', 'GDP stands for Gross Domestic Product, the primary indicator of national economic output.'),
        ('eco11-10-sd-0044', 10, 'What does the state-level macroeconomic abbreviation ''GSDP'' stand for?', 'Gross State Domestic Product', 'General State Development Programme', 'a', 1, 'The state equivalent of national GDP.', 'GSDP stands for Gross State Domestic Product, quantifying the economic output produced within a particular state.'),
        ('eco11-10-sd-0045', 10, 'What does the demographic acronym ''NFHS'' stand for in India?', 'National Family Health Survey', 'National Finance and Health Scheme', 'a', 1, 'The extensive nationwide household health survey.', 'NFHS stands for National Family Health Survey, providing essential demographic and health indicators.'),
        ('eco11-10-sd-0046', 10, 'What is the official expansion of the acronym ''NITI'' in NITI Aayog?', 'National Institute for Trade in India', 'National Institution for Transforming India', 'b', 1, 'Formed in 2015 to transform governance and planning.', 'NITI stands for National Institution for Transforming India.'),
        ('eco11-10-sd-0047', 10, 'What does the food and essential goods welfare acronym ''PDS'' stand for?', 'Private Distribution System', 'Public Distribution System', 'b', 1, 'The government network of ration and fair-price shops.', 'PDS stands for Public Distribution System, which distributes subsidised foodgrains to households.'),
        ('eco11-10-sd-0048', 10, 'What does the economic development abbreviation ''SEZ'' stand for?', 'State Economic Zones', 'Special Economic Zones', 'b', 1, 'Designated duty-free enclaves to boost export manufacturing.', 'SEZ stands for Special Economic Zones, which offer special regulatory and tax incentives for export-oriented production.'),
        ('eco11-10-sd-0049', 10, 'Which national apex financial institution is designated by the acronym ''NABARD''?', 'National Disaster Management Authority', 'National Bank for Agriculture and Rural Development', 'b', 1, 'The apex bank dedicated to rural credit and agricultural development.', 'NABARD stands for National Bank for Agriculture and Rural Development.'),
        ('eco11-10-sd-0050', 10, 'Which educational rights acronym stands for ''Right to Education'' in India?', 'RTE', 'RBI', 'a', 1, 'An Act ensuring free and compulsory schooling for children.', 'RTE stands for Right to Education, enacted to ensure fundamental school education for all children.')
    ) AS v (question_code, chapter_no, prompt, option_a, option_b, correct_option, difficulty, hint, explanation)
) AS s
ON t.question_code = s.question_code
WHEN MATCHED AND (t.subject, t.chapter_no, t.prompt, t.option_a, t.option_b, t.correct_option, t.difficulty, t.hint, t.explanation) IS DISTINCT FROM (s.subject, s.chapter_no, s.prompt, s.option_a, s.option_b, s.correct_option, s.difficulty, s.hint, s.explanation) THEN
    UPDATE SET subject = s.subject, chapter_no = s.chapter_no, prompt = s.prompt, option_a = s.option_a, option_b = s.option_b, correct_option = s.correct_option, difficulty = s.difficulty, hint = s.hint, explanation = s.explanation
WHEN NOT MATCHED THEN
    INSERT (question_code, subject, chapter_no, prompt, option_a, option_b, correct_option, difficulty, hint, explanation) VALUES (s.question_code, s.subject, s.chapter_no, s.prompt, s.option_a, s.option_b, s.correct_option, s.difficulty, s.hint, s.explanation)
WHEN NOT MATCHED BY SOURCE AND t.subject = 'economics' THEN
    DELETE;
